1	using System;
2	using System.Collections.Generic;
3	using System.Linq;
4	using Anthro.Sim.Activities;
5	using Anthro.Sim.Core;
6	using Anthro.Sim.Discovery;
7	using Anthro.Sim.Ecology;
8	using Anthro.Sim.People;
9	using Anthro.Sim.World;
10	
11	namespace Anthro.Sim
12	{
13	    public sealed class YearStats
14	    {
15	        public int Year;
16	        public int Births;
17	        public int Population;
18	        public double AvgSatiety, AvgHealth, Valor, Caution, Sharing;
19	        public int SickDays, Couples;
20	        public double Gathered, Hunted, Eaten, Spoiled, Needed, Shared, CookingGain;
21	        public int FireOutDays;
22	        public int Refusals, Thefts, Fights, Raids;
23	        public readonly Dictionary<Activities.Verb, long> Hours = new Dictionary<Activities.Verb, long>();
24	        internal int Samples;
25	        public readonly Dictionary<string, int> Deaths = new Dictionary<string, int>();
26	        public readonly Dictionary<string, int> Kills = new Dictionary<string, int>();
27	    }
28	
29	    /// <summary>
30	    /// One valley, one band. <see cref="Step"/> advances one in-game hour. Everything is driven by
31	    /// a single seed, so the same seed always replays the same history.
32	    /// </summary>
33	    public sealed partial class Simulation
34	    {
35	        public readonly Rng Rng;
36	        public readonly SimClock Clock = new SimClock();
37	        public readonly Chronicle Chronicle = new Chronicle();
38	        public readonly WorldMap World;
39	        public readonly EcologySystem Ecology = new EcologySystem();
40	        public readonly Band Band = new Band();
41	        public readonly DiscoveryWeb? Web;
42	        public readonly List<NeighborBand> Neighbors = new List<NeighborBand>();
43	
44	        /// <summary>Neighbors' adults currently visiting the camp.</summary>
45	        public IEnumerable<Person> Visitors => Neighbors.Where(n => n.Visiting).SelectMany(n => n.People).Where(p => p.AgeYears(Clock) >= 14);
46	
47	        /// <summary>Best plant patches near camp, refreshed daily so foragers don't each scan the map.</summary>
48	        public readonly List<Cell> ForagePatches = new List<Cell>();
49	
50	        public YearStats ThisYear { get; private set; } = new YearStats();
51	        public event Action<YearStats>? YearEnded;
52	
53	        readonly Names _names = new Names();
54	        readonly HashSet<Species> _killedBefore = new HashSet<Species>();
55	        int _nextPersonId;
56	        long _campSince;
57	        bool _wolvesSeenThisSeason, _hungerReportedThisSeason;
58	        /// <summary>How hard life has been lately: hunger, smoothed over roughly a season.</summary>
59	        double _hardship;
60	
61	        static readonly string[] DefaultKnown = { "fire.make", "knap.flake", "knap.blade", "spear.wood", "forage.rounds", "lang.speech", "wood.shape", "shelter.brush" };
62	
63	        Simulation(ulong seed, DiscoveryWeb? web)
64	        {
65	            Rng = new Rng(seed);
66	            Web = web;
67	            World = WorldGen.Generate(Rng.Fork(1));
68	            Ecology.Populate(this);
69	        }
70	
71	        public static Simulation Create(ulong seed, DiscoveryWeb? web = null, int bandSize = 30)
72	        {
73	            var sim = new Simulation(seed, web);
74	            sim.FoundBand(bandSize);
75	            return sim;
76	        }
77	
78	        public bool Extinct => Band.Members.Count == 0;
79	
80	        public void Step()
81	        {
82	            if (Clock.Hour == 0) using (Profiler.Measure("daily")) Daily();
83	
84	            foreach (var p in Band.Members.ToList())
85	            {
86	                // Someone who died or left with their family earlier this hour is no longer here.
87	                if (!p.Alive || p.LeftDay == Clock.Day && !Band.Members.Contains(p)) continue;
88	                Metabolize(p);
89	                if (p.Current != null && p.AgeYears(Clock) >= 14) ThisYear.Hours[p.Current.Verb] = (ThisYear.Hours.TryGetValue(p.Current.Verb, out var h) ? h : 0) + 1;
90	                if (p.Current == null || p.Current.Done)
91	                {
92	                    using (Profiler.Measure("decide")) p.Current = Decider.Choose(this, p);
93	                    using (Profiler.Measure("begin " + p.Current.Verb)) p.Current.Begin(this);
94	                }
95	                using (Profiler.Measure("hour " + p.Current.Verb)) p.Current.Hour(this);
96	            }
97	
98	            Clock.Advance();
99	            if (Clock.Tick % (SimClock.HoursPerDay * SimClock.DaysPerYear) == 0) EndYear();
100	        }
101	
102	        public void RunYears(int years)
103	        {
104	            long end = Clock.Tick + (long)years * SimClock.HoursPerDay * SimClock.DaysPerYear;
105	            while (Clock.Tick < end && !Extinct) Step();
106	        }
107	
108	        // ---- Founding ------------------------------------------------------------------------
109	
110	        void FoundBand(int size)
111	        {
112	            Band.Name = _names.Next(Rng);
113	            for (int i = 0; i < TraitCounts.Mind; i++) Band.AttractionMind[i] = Rng.Normal(0, 0.2);
114	            for (int i = 0; i < TraitCounts.Body; i++) Band.AttractionBody[i] = Rng.Normal(0, 0.2);
115	
116	            var camp = ScoreCampSites(30).First();
117	            Band.CampX = camp.X; Band.CampY = camp.Y;
118	
119	            // A typical forager band: about a quarter couples, a few elders and young adults, the rest children.
120	            int couples = Math.Max(1, (int)Math.Round(size * 0.25));
121	            int elders = Math.Max(1, size / 10);
122	            int youths = Math.Max(1, size / 10);
123	            var parents = new List<(Person mother, Person father, double motherAge)>();
124	            for (int i = 0; i < couples; i++)
125	            {
126	                double womanAge = Rng.Range(18, 38);
127	                var woman = NewFounder(womanAge, Sex.Female);
128	                var man = NewFounder(Math.Max(16, womanAge + Rng.Range(-2, 8)), Sex.Male);
129	                woman.Partner = man; man.Partner = woman;
130	                woman.AddAffinity(man, 0.6); man.AddAffinity(woman, 0.6);
131	                NewHousehold(woman, man);
