354	        /// A day in a body. Each harm is booked against its cause, so a death is always explained
355	        /// by what actually wore the person down.
356	        /// </summary>
357	        void DailyBody(Person p, double temp)
358	        {
359	            double age = p.AgeYears(Clock);
360	            // Each harm is booked against its cause in a ledger that fades over a few weeks, so a death
361	            // is attributed to whatever really wore the person down, not just the last day's blow.
362	            foreach (var key in p.HarmLedger.Keys.ToList()) p.HarmLedger[key] *= 0.93;
363	            var harm = p.HarmLedger;
364	            void Hurt(string cause, double amount)
365	            {
366	                if (amount <= 0) return;
367	                p.Health -= amount;
368	                harm[cause] = (harm.TryGetValue(cause, out var h) ? h : 0) + amount;
369	            }
370	
371	            // Outright starvation only when the body's reserves are all but gone. Before that,
372	            // short rations do their damage by weakening people against sickness.
373	            if (p.Satiety < 0.15) Hurt("starvation", (0.15 - p.Satiety) * 0.2);
374	
375	            double cold = Math.Max(0, (Shelter.ComfortTemp(Band, p) - temp) / 20.0 - p.B(BodyTrait.ColdTolerance) * 0.3 - p.B(BodyTrait.Build) * 0.1);
376	            if (age < 5 || age > 60) cold *= 1.5;
377	            // Sleeping close to family shares body heat; small children sleep against their parents.
378	            if (HasSleepingFamily(p)) cold *= 0.6;
379	            p.ColdStress = cold;
380	            // Cold mostly kills by weakening people against sickness; it freezes outright only when severe.
381	            Hurt("cold", Math.Max(0, cold - 0.3) * 0.05);
382	
383	            Infection(p, age, cold);
384	            if (p.Illness != null)
385	            {
386	                // The body's response builds over the days of a sickness, so most illnesses peak and pass.
387	                var d = p.Illness;
388	                p.SickDays++;
389	                double fight = Physiology.ImmuneStrength(p, age) * 0.08 * (1 + p.SickDays * 0.15)
390	                               + Math.Min(4, p.CareToday) * 0.012 + (p.Current is Rest || p.Current is Sleep ? 0.02 : 0);
391	                p.Sickness += d.Growth * (age < 5 ? d.ChildRisk : 1) - fight;
392	                if (p.Sickness <= 0)
393	                {
394	                    p.Sickness = 0; p.Illness = null; p.SickDays = 0;
395	                    if (d.ImmunityGain > 0) p.Immunities[d] = Math.Max(p.ImmunityTo(d), d.ImmunityGain);
396	                }
397	                else Hurt(d.DiedOf, p.Sickness * d.Harm * (age < 5 ? d.ChildRisk : 1));
398	            }
399	            foreach (var d in p.Immunities.Keys.ToList()) p.Immunities[d] = Math.Max(0, p.Immunities[d] - d.ImmunityFade);
400	
401	            p.Injury = Math.Max(0, p.Injury - 0.01 * (0.5 + p.B(BodyTrait.Endurance)));
402	            if (p.Satiety >= 0.35 && p.Sickness == 0) p.Health += 0.01 * (age > 50 ? 0.6 : 1);
403	            p.Health = Math.Min(p.Health, Physiology.MaxHealth(age) - p.Injury * 0.5);
404	
405	            // People remember how lean winter was; the memory spreads like any belief and drives autumn stockpiling.
406	            // People remember the worst of a winter, not the average, and that memory spreads like any
407	            // belief, driving autumn stockpiling.
408	            if (Clock.Season == Season.Winter) p.WinterLow = Math.Min(p.WinterLow, p.Satiety);
409	            if (Clock.Season == Season.Spring && Clock.DayOfSeason == 20 && age >= 10)
410	            {
411	                // A hard winter is unforgettable: the lesson lands at once, hardest on the less resilient.
412	                p.Expect.Absorb("lean:winter", 1 - p.WinterLow, 0.3 + 0.3 * (1 - p.M(MindTrait.Resilience)), 0.2);
413	                p.WinterLow = 1;
414	            }
415	
416	            p.CareToday = 0;
417	            p.Fatigue *= 0.9;
418	            if (!p.Restless && age >= 20 && Rng.Chance(Crowding(p) * 0.02)) p.Restless = true;
419	            if (age < 12) DriftTowardParents(p);
420	
421	            if (p.Health > 0) return;
422	            string cause = harm.Count == 0 ? (p.Injury > 0.5 ? "wounds" : "old age") : harm.OrderByDescending(kv => kv.Value).First().Key;
423	            var weakened = new List<string>();
424	            if (Environment.GetEnvironmentVariable("ANTHRO_DEBUG_DEATHS") != null)
425	                Console.Error.WriteLine($"DEATH {p.Name} age {age:F1} {Clock.Season} cause {cause} | ledger {string.Join(", ", harm.Select(kv => $"{kv.Key} {kv.Value:F2}"))} | reserve {p.Reserve:F2} stomach {p.Stomach:F2} home food {p.Home?.Food.Total ?? 0:F1} camp food {Band.FoodTotal:F0} for {Band.Members.Count} | sick {p.Illness?.Name ?? "-"} | doing {p.Current} | expect forage {p.Expect.Get(Verb.Forage, 0):F2} hunt {p.Expect.Get(Verb.Hunt, 0):F2} | home size {p.Home?.Members.Count ?? 0} fuel {p.Home?.Fuel ?? 0:F1}");
426	            if (cause != "starvation" && p.Satiety < 0.5) weakened.Add("hunger");
427	            if (cause != "cold" && p.ColdStress > 0.15) weakened.Add("cold");
428	            if (Physiology.MaxHealth(age) < 0.3 && cause != "old age") weakened.Add("age");
429	            Kill(p, cause, weakened.Count == 0 ? null : "weakened by " + string.Join(" and ", weakened));
430	        }
