432	        /// <summary>
433	        /// Sickness always comes from somewhere that isn't another person: a fouled camp, rotten
434	        /// meat, an open wound, or (for someone already sick) a winter chill settling in the lungs.
435	        /// Catching diseases from people happens through <see cref="Contact"/>.
436	        /// </summary>
437	        void Infection(Person p, double age, double coldStress)
438	        {
439	            double immune = Physiology.ImmuneStrength(p, age);
440	            if (p.Illness != null)
441	            {
442	                // A chill on top of another sickness can turn into lung sickness, worst for the old.
443	                if (p.Illness != Disease.LungSickness && coldStress > 0.1 && Rng.Chance(coldStress * 0.05 * (age > 60 ? 2 : 1) * (1.3 - immune)))
444	                {
445	                    p.Illness = Disease.LungSickness;
446	                    p.Sickness = Math.Max(p.Sickness, 0.3);
447	                    p.SickDays = 0;
448	                }
449	                return;
450	            }
451	            double weak = 1.3 - immune;
452	            // Colds are always around in any human group, and spread more when people huddle in winter.
453	            double coldSeason = Clock.Season == Season.Winter ? 3 : Clock.Season == Season.Autumn ? 1.5 : 1;
454	            // Small children catch everything going: their bodies haven't met these germs yet.
455	            double young = age < 5 ? 2.5 : age < 14 ? 1.5 : 1;
456	            if (Rng.Chance(0.004 * coldSeason * young * weak * (1 - p.ImmunityTo(Disease.Cold)))) { p.Catch(Disease.Cold, Rng.Range(0.1, 0.3)); return; }
457	            // Gut infections are always around for small children, from weaning food and dirt.
458	            if (age < 5 && Rng.Chance(0.0015 * weak * (1 - p.ImmunityTo(Disease.Flux)))) { p.Catch(Disease.Flux, Rng.Range(0.1, 0.3)); return; }
459	            // Fevers carried by insects and water turn up now and then, more in the warm months.
460	            double warm = Clock.Season == Season.Summer ? 2 : Clock.Season == Season.Winter ? 0.2 : 1;
461	            if (Rng.Chance(0.0003 * warm * young * weak * (1 - p.ImmunityTo(Disease.Fever)))) { p.Catch(Disease.Fever, Rng.Range(0.15, 0.35)); return; }
462	            if (p.AteRotten && Rng.Chance(0.3 * weak)) { p.Catch(Disease.BadMeat, Rng.Range(0.15, 0.35)); return; }
463	            if (p.Injury > 0.2 && Rng.Chance(p.Injury * 0.03 * weak)) { p.Catch(Disease.WoundRot, Rng.Range(0.2, 0.4)); return; }
464	            double filth = Band.Filth * 0.0004 * (age < 5 ? 2 : 1);
465	            if (Rng.Chance(filth * weak * (1 - p.ImmunityTo(Disease.Flux)))) p.Catch(Disease.Flux, Rng.Range(0.15, 0.4));
466	        }
