478	        void Pass(Person from, Person to, double hours)
479	        {
480	            var d = from.Illness;
481	            if (d == null || d.Contagion <= 0 || to.Illness != null || !to.Alive) return;
482	            double resist = Physiology.ImmuneStrength(to, to.AgeYears(Clock));
483	            double chance = d.Contagion * from.Sickness * hours * (1.3 - resist) * (1 - to.ImmunityTo(d));
484	            if (Rng.Chance(chance)) to.Catch(d, Rng.Range(0.1, 0.3));
485	        }
