593	        /// <summary>
594	        /// Two people pair. If they come from different bands, whoever is less tied to their own
595	        /// people moves.
596	        /// </summary>
597	        public void Pair(Person a, Person b)
598	        {
599	            a.Partner = b; b.Partner = a;
600	            a.AddAffinity(b, 0.3); b.AddAffinity(a, 0.3);
601	            bool aHere = Band.Members.Contains(a), bHere = Band.Members.Contains(b);
602	            if (aHere && bHere)
603	            {
604	                NewHousehold(a, b);
605	                Chronicle.Write(Clock, Importance.Detail, $"{a.Name} and {b.Name} paired.");
606	                return;
607	            }
608	            var local = aHere ? a : b;
609	            var visitor = aHere ? b : a;
610	            var home = Neighbors.First(n => n.People.Contains(visitor));
611	            // Each weighs what leaving would cost them against what they'd gain on the other side,
612	            // plus whatever custom the band has formed about who moves. Whoever loses less moves.
613	            double residence = Band.ResidenceNorm * (visitor.Sex == Sex.Female ? 1 : -1);
614	            // Neighbors' hunger isn't simulated yet; people assume they're doing about as well as most.
615	            double theirProspects = 0.8, ourProspects = Prospects;
616	            double visitorCost = Ties(visitor, home.People) - Ties(visitor, Band.Members) * 0.5 - residence - (ourProspects - theirProspects) * 4;
617	            double localCost = Ties(local, Band.Members) - Ties(local, home.People) * 0.5 + residence - (theirProspects - ourProspects) * 4;
618	            bool visitorMoves = visitorCost <= localCost;
619	            var mover = visitorMoves ? visitor : local;
620	            var partner = visitorMoves ? local : visitor;
621	            // A custom about who moves forms from what people actually do.
622	            Band.ResidenceNorm += ((mover.Sex == Sex.Female ? 1 : -1) - Band.ResidenceNorm) * 0.1;
623	            if (visitorMoves)
624	            {
625	                home.People.Remove(visitor);
626	                visitor.X = Band.CampX; visitor.Y = Band.CampY;
627	                Band.Members.Add(visitor);
628	                NewHousehold(visitor, local);
629	                Chronicle.Write(Clock, Importance.Notable, $"{visitor.Name} of the {home.Name} band paired with {local.Name} and joined the band.");
630	            }
631	            else
632	            {
633	                // Young children with no other parent here go with them.
634	                var kids = local.Children.Where(c => c.Alive && c.AgeYears(Clock) < 14 && Band.Members.Contains(c)
635	                                                     && !(c.Mother != local && c.Mother != null && Band.Members.Contains(c.Mother))
636	                                                     && !(c.Father != local && c.Father != null && Band.Members.Contains(c.Father))).ToList();
637	                Depart(new List<Person> { local }.Concat(kids).ToList(), home);
638	                Chronicle.Write(Clock, Importance.Notable, $"{local.Name} paired with {visitor.Name} and left to live with the {home.Name} band.");
639	            }
640	        }
