852	        /// <summary>
853	        /// A year living apart: bonds with everyone outside the group fade the way unattended bonds
854	        /// fade in camp (the same daily rate, a year's worth), down to the floor kin never fall below.
855	        /// </summary>
856	        static void FadeBondsApart(List<Person> group)
857	        {
858	            double keep = Math.Pow(1 - 0.003, SimClock.DaysPerYear);
859	            var here = new HashSet<int>(group.Select(g => g.Id));
860	            foreach (var p in group)
861	            {
862	                var kin = new HashSet<int>(new[] { p.Mother, p.Father, p.Partner }.Concat(p.Children)
863	                    .Concat(p.Mother?.Children ?? Enumerable.Empty<Person>()).Where(k => k != null).Select(k => k!.Id));
864	                foreach (var id in p.Affinity.Keys.ToList())
865	                {
866	                    if (here.Contains(id)) continue;
867	                    double floor = kin.Contains(id) ? 0.4 : 0.05;
868	                    double v = p.Affinity[id];
869	                    if (v > floor) p.Affinity[id] = floor + (v - floor) * keep;
870	                }
871	            }
872	        }
