874	        void MatureBonds(List<Person> group)
875	        {
876	            var ourAdults = Band.Members.Where(m => m.AgeYears(Clock) >= 16).ToList();
877	            var theirAdults = group.Where(m => m.AgeYears(Clock) >= 16).ToList();
878	            if (ourAdults.Count == 0 || theirAdults.Count == 0) return;
879	            double ours = ourAdults.Average(m => Ties(m, Band.Members));
880	            double theirs = theirAdults.Average(m => Ties(m, group));
881	            if (theirs <= 0) return;
882	            double scale = Math.Min(3, ours / theirs);
883	            foreach (var x in group)
884	                foreach (var y in group)
885	                {
886	                    if (x == y) continue;
887	                    // Living together for a year makes everyone at least familiar.
888	                    if (x.GetAffinity(y) < 0.15) x.AddAffinity(y, 0.15 - x.GetAffinity(y));
889	                    x.AddAffinity(y, x.GetAffinity(y) * (scale - 1));
890	                }
891	        }
