912	        /// <summary>
913	        /// How good someone thinks foraging is around the current camp this season: the best few
914	        /// nearby places they remember from this time of year.
915	        /// </summary>
916	        double LocalValue(Person p)
917	        {
918	            double a = 0, b = 0, c = 0;
919	            foreach (var kv in p.Places[(int)Clock.Season])
920	            {
921	                var (x, y) = Person.FromPlaceKey(kv.Key);
922	                if (WorldMap.Distance(x, y, Band.CampX, Band.CampY) > WorldMap.FromMeters(4000)) continue;
923	                double v = kv.Value;
924	                if (v > a) { c = b; b = a; a = v; } else if (v > b) { c = b; b = v; } else if (v > c) c = v;
925	            }
926	            int n = (a > 0 ? 1 : 0) + (b > 0 ? 1 : 0) + (c > 0 ? 1 : 0);
927	            double here = n > 0 ? (a + b + c) / n : p.Expect.Get(Verb.Forage, Forage.FallbackPerHour);
