932	        /// <summary>
933	        /// Someone who remembers a better place than what they've been finding lately may propose
934	        /// moving there. Each adult weighs it: their own memory of the place if they have one,
935	        /// otherwise how much they trust whoever proposed it. Influence decides.
936	        /// </summary>
937	        public void ConsiderMoving(Person proposer)
938	        {
939	            if (proposer.LastProposalDay == Clock.Day || !Band.Members.Contains(proposer) || proposer.AgeYears(Clock) < 18) return;
940	            proposer.LastProposalDay = Clock.Day;
941	            proposer.Restless = false;
942	            var memory = proposer.Places[(int)Clock.Season];
943	            if (memory.Count == 0) { ConsiderSplitting(proposer); return; }
944	            double local = LocalValue(proposer);
945	            int bestKey = -1; double bestValue = 0;
946	            foreach (var kv in memory)
947	            {
948	                var (x, y) = Person.FromPlaceKey(kv.Key);
949	                double d = WorldMap.Distance(x, y, Band.CampX, Band.CampY);
950	                if (d < WorldMap.FromMeters(1500)) continue;
951	                double v = kv.Value - d * WorldMap.CellMeters / 1000 * 0.015;
952	                if (v > bestValue) { bestValue = v; bestKey = kv.Key; }
953	            }
954	            // The gain has to outweigh the effort of moving.
955	            if (bestKey < 0 || bestValue - local <= 0.1 + 0.3 * StayPull) { ConsiderSplitting(proposer); return; }
956	
957	            double yes = 0, no = 0;
958	            foreach (var a in Band.Members.Where(m => m.AgeYears(Clock) >= 16))
959	            {
960	                double mine = LocalValue(a);
961	                double trust = a == proposer ? 1 : Inheritance.Clamp01(a.GetAffinity(proposer) * (0.5 + proposer.M(MindTrait.Charisma)));
962	                double theirs = a.Places[(int)Clock.Season].TryGetValue(bestKey, out var known) ? known : mine + (bestValue - mine) * trust;
963	                double weight = 0.5 + a.M(MindTrait.Charisma) + a.Prestige * 0.3 + a.AgeYears(Clock) / 60;
964	                if (theirs - mine > 0.05 + 0.3 * StayPull) yes += weight; else no += weight;
965	            }
966	            if (yes <= no) { ConsiderSplitting(proposer); return; }
967	
968	            var (tx, ty) = Person.FromPlaceKey(bestKey);
969	            double ddx = tx - Band.CampX, ddy = ty - Band.CampY;
970	            string dir = Math.Abs(ddx) > Math.Abs(ddy) ? (ddx > 0 ? "east" : "west") : (ddy > 0 ? "south" : "north");
971	            Band.CampX = tx; Band.CampY = ty;
972	            _campSince = Clock.Day;
973	            Band.Filth = 0;
974	            RefreshForagePatches();
975	            Chronicle.Write(Clock, Importance.Notable, $"On {proposer.Name}'s urging, the band moved camp {dir}, to the {World[tx, ty].Terrain.ToString().ToLower()}.");
976	        }
