        /// <summary>
        /// How much of the camp is near-strangers to this person. A person's circle is a few dozen
        /// people at most; past that, a big camp brings friction.
        /// </summary>
        double Crowding(Person p)
        {
            int n = Band.Members.Count;
            if (n <= 1) return 0;
            int bonded = 0;
            foreach (var o in Band.Members) if (o != p && p.GetAffinity(o) > 0.1) bonded++;
            return Math.Max(0, 1 - bonded / (double)(n - 1)) * Math.Min(1, n / 60.0);
        }

        /// <summary>How well-off the band looks: people notice hunger.</summary>
        double Prospects => Band.Members.Count == 0 ? 0 : Band.Members.Average(m => m.Satiety);

        // ---- Neighbors -------------------------------------------------------------------------

        /// <summary>The valley sits in the middle of a region three times its width.</summary>
        double RegionMin => -World.Size;
        double RegionMax => World.Size * 2;

        NeighborBand NewNeighborBand()
        {
            var n = new NeighborBand { Name = _names.Next(Rng) };
            n.X = Rng.Range(RegionMin, RegionMax); n.Y = Rng.Range(RegionMin, RegionMax);
            n.TargetX = n.X; n.TargetY = n.Y;
            int size = Rng.Range(18, 30);
            int couples = Math.Max(1, (int)Math.Round(size * 0.25));
            var parents = new List<(Person mother, Person father, double motherAge)>();
            for (int i = 0; i < couples; i++)
            {
                double womanAge = Rng.Range(18, 38);
                var woman = MakeStranger(womanAge, Sex.Female);
                var man = MakeStranger(Math.Max(16, womanAge + Rng.Range(-2, 8)), Sex.Male);
                woman.Partner = man; man.Partner = woman;
                n.People.Add(woman); n.People.Add(man);
                parents.Add((woman, man, womanAge));
            }
            for (int i = 0; i < Math.Max(1, size / 10); i++) n.People.Add(MakeStranger(Rng.Range(48, 63), Rng.Chance(0.5) ? Sex.Female : Sex.Male));
            while (n.People.Count < size)
            {
                var (mother, father, motherAge) = parents[Rng.Range(0, parents.Count)];
                n.People.Add(MakeChildOf(mother, father, Rng.Range(0, Math.Max(1, Math.Min(13, motherAge - 16)))));
            }
            KnitTogether(n.People);
            SeedCulture(n.People);
            return n;
        }

        /// <summary>
        /// Neighbors wander the region. When their wandering brings them near the camp they visit;
        /// they stay longer the friendlier the two bands are.
        /// </summary>
        /// <summary>
        /// Bookkeeping check for tests: everyone is in exactly one place (this band or one neighbor
        /// band), and households list exactly the band's members whose home they are.
        /// </summary>
        public void CheckPlaces(string where = "")
        {
            var seen = new HashSet<Person>();
            foreach (var m in Band.Members.Concat(Neighbors.SelectMany(n => n.People)))
                if (!seen.Add(m)) throw new Exception($"DUP@{where} {m.Name}#{m.Id} day {Clock.Day} inBand={Band.Members.Count(x => x == m)} inNeighbors={string.Join(",", Neighbors.Where(n => n.People.Contains(m)).Select(n => n.Name + ":" + n.People.Count(x => x == m)))} home={m.Home?.Id} age={m.AgeYears(Clock):F1}");
            var inHH = new HashSet<Person>();
            foreach (var h in Band.Households) foreach (var m in h.Members)
                if (!inHH.Add(m)) throw new Exception($"TWOHH@{where} {m.Name} day {Clock.Day} hour {Clock.Hour} age={m.AgeYears(Clock):F1} counts={string.Join(",", Band.Households.Where(x => x.Members.Contains(m)).Select(x => x.Id + "x" + x.Members.Count(y => y == m) + (m.Home == x ? "*" : "")))}");
            foreach (var h in Band.Households)
                foreach (var m in h.Members)
                    if (!Band.Members.Contains(m) || m.Home != h)
                        throw new Exception($"HH@{where} {m.Name}#{m.Id} day {Clock.Day} hour {Clock.Hour} inBand={Band.Members.Contains(m)} homeMatches={m.Home == h} alive={m.Alive} age={m.AgeYears(Clock):F1} inNeighbor={Neighbors.Any(n => n.People.Contains(m))}");
            foreach (var m in Band.Members)
                if (m.Home != null && !m.Home.Members.Contains(m)) throw new Exception($"HOME@{where} {m.Name} day {Clock.Day}");
        }

        void MoveNeighbors()
        {
            foreach (var gone in Neighbors.Where(n => n.People.Count == 0).ToList())
            {
                Neighbors.Remove(gone);
                Chronicle.Write(Clock, Importance.Notable, $"The {gone.Name} band is no more.");
            }
            foreach (var n in Neighbors)
            {
                Outbreaks(n);
                double friendliness = n.Visiting && Band.Members.Count > 0
                    ? n.People.Average(v => Band.Members.Max(m => v.GetAffinity(m)))
                    : 0;
                bool arrived = WorldMap.Distance(n.X, n.Y, n.TargetX, n.TargetY) < WorldMap.FromMeters(500);
                if (arrived && Rng.Chance(n.Visiting ? Math.Max(0.02, 0.12 - friendliness * 0.1) : 0.2))
                {
                    n.TargetX = Rng.Range(RegionMin, RegionMax);
                    n.TargetY = Rng.Range(RegionMin, RegionMax);
                }
                double dx = n.TargetX - n.X, dy = n.TargetY - n.Y, d = Math.Sqrt(dx * dx + dy * dy);
                if (d > 0.01) { double step = Math.Min(WorldMap.FromMeters(8000), d) / d; n.X += dx * step; n.Y += dy * step; }

                double toCamp = WorldMap.Distance(n.X, n.Y, Band.CampX, Band.CampY);
                if (!n.Visiting && toCamp < WorldMap.FromMeters(3000))
                {
                    n.Visiting = true;
                    n.TargetX = n.X; n.TargetY = n.Y;
                    ConsiderReturns(n);
                    Chronicle.Write(Clock, Importance.Notable, $"The {n.Name} band made camp nearby.");
                }
                else if (n.Visiting && toCamp > WorldMap.FromMeters(5000))
                {
                    n.Visiting = false;
                    Chronicle.Write(Clock, Importance.Detail, $"The {n.Name} band moved on.");
                }
            }
            if (Clock.DayOfYear == 0) RenewNeighbors();
        }

        /// <summary>
        /// Neighbors' lives aren't simulated yet: each year their elders pass and their children
        /// come of age, keeping the band's size and age spread.
        /// </summary>
        void RenewNeighbors()
        {
            foreach (var n in Neighbors)
            {
                n.People.RemoveAll(p => p.AgeYears(Clock) > 65);
                FadeBondsApart(n.People);
                MatureBonds(n.People);
                var couples = n.People.Where(p => p.Sex == Sex.Female && p.Partner != null && n.People.Contains(p.Partner)).ToList();
                while (n.People.Count < 22 && couples.Count > 0)
                {
                    var mother = couples[Rng.Range(0, couples.Count)];
                    var child = MakeChildOf(mother, mother.Partner!, 0);
                    foreach (var o in n.People) { child.AddAffinity(o, 0.2); o.AddAffinity(child, 0.2); }
                    n.People.Add(child);
                }
            }
        }

        /// <summary>
        /// Neighbors' health isn't simulated day to day. Now and then a cold or a fever runs through
        /// a band in the region; its sick recover over a few weeks. If they visit while it's going
        /// around, it can spread to our people through ordinary contact.
        /// </summary>
        void Outbreaks(NeighborBand n)
        {
            foreach (var p in n.People)
            {
                if (p.Illness == null) continue;
                p.Sickness -= 0.04;
                if (p.Sickness <= 0) { p.Sickness = 0; p.Immunities[p.Illness] = p.Illness.ImmunityGain; p.Illness = null; }
            }
            if (!Rng.Chance(0.003) || n.People.Count == 0) return;
            var d = Rng.Chance(0.6) ? Disease.Cold : Disease.Fever;
            foreach (var p in n.People)
                if (Rng.Chance(0.3 * (1 - p.ImmunityTo(d)))) p.Catch(d, Rng.Range(0.2, 0.5));
        }

        /// <summary>
        /// Neighbors' daily lives aren't simulated, so their friendships can't deepen the way ours
        /// do. Each year their bonds are scaled so a typical neighbor is as tied to their people as a
        /// typical one of ours, so that both sides weigh the same when a couple decides who moves.
        /// </summary>
        /// <summary>
        /// A year living apart: bonds with everyone outside the group fade the way unattended bonds
        /// fade in camp (the same daily rate, a year's worth), down to the floor kin never fall below.
        /// </summary>
        static void FadeBondsApart(List<Person> group)
        {
            double keep = Math.Pow(1 - 0.003, SimClock.DaysPerYear);
            var here = new HashSet<int>(group.Select(g => g.Id));
            foreach (var p in group)
            {
                var kin = new HashSet<int>(new[] { p.Mother, p.Father, p.Partner }.Concat(p.Children)
                    .Concat(p.Mother?.Children ?? Enumerable.Empty<Person>()).Where(k => k != null).Select(k => k!.Id));
                foreach (var id in p.Affinity.Keys.ToList())
                {
                    if (here.Contains(id)) continue;
                    double floor = kin.Contains(id) ? 0.4 : 0.05;
                    double v = p.Affinity[id];
                    if (v > floor) p.Affinity[id] = floor + (v - floor) * keep;
                }
            }
        }

        void MatureBonds(List<Person> group)
        {
            var ourAdults = Band.Members.Where(m => m.AgeYears(Clock) >= 16).ToList();
            var theirAdults = group.Where(m => m.AgeYears(Clock) >= 16).ToList();
            if (ourAdults.Count == 0 || theirAdults.Count == 0) return;
            double ours = ourAdults.Average(m => Ties(m, Band.Members));
            double theirs = theirAdults.Average(m => Ties(m, group));
            if (theirs <= 0) return;
            double scale = Math.Min(3, ours / theirs);
            foreach (var x in group)
                foreach (var y in group)
                {
                    if (x == y) continue;
                    // Living together for a year makes everyone at least familiar.
                    if (x.GetAffinity(y) < 0.15) x.AddAffinity(y, 0.15 - x.GetAffinity(y));
                    x.AddAffinity(y, x.GetAffinity(y) * (scale - 1));
                }
        }

        // ---- Moving camp -----------------------------------------------------------------------

        /// <summary>
        /// The pull of staying: attachment grows with time at a camp, weariness from the last move
        /// fades over weeks, and carrying small children and the old makes every move harder.
        /// </summary>
        double StayPull
        {
            get
            {
                double days = Clock.Day - _campSince;
                double attachment = Math.Min(1, days / 180.0) * 0.25;
                double weariness = Math.Exp(-days / 30.0) * 0.6;
                int n = Math.Max(1, Band.Members.Count);
                double burden = Band.Members.Count(m => { var a = m.AgeYears(Clock); return a < 5 || a > 60; }) / (double)n * 0.5;
                return attachment + weariness + burden;
            }
        }

        /// <summary>
        /// How good someone thinks foraging is around the current camp this season: the best few
        /// nearby places they remember from this time of year.
        /// </summary>
        double LocalValue(Person p)
        {
            double a = 0, b = 0, c = 0;
            foreach (var kv in p.Places[(int)Clock.Season])
            {
                var (x, y) = Person.FromPlaceKey(kv.Key);
                if (WorldMap.Distance(x, y, Band.CampX, Band.CampY) > WorldMap.FromMeters(4000)) continue;
                double v = kv.Value;
                if (v > a) { c = b; b = a; a = v; } else if (v > b) { c = b; b = v; } else if (v > c) c = v;
            }
            int n = (a > 0 ? 1 : 0) + (b > 0 ? 1 : 0) + (c > 0 ? 1 : 0);
            double here = n > 0 ? (a + b + c) / n : p.Expect.Get(Verb.Forage, Forage.FallbackPerHour);
            // A fouled camp makes staying feel worse.
            return here - Band.Filth * 0.02;
        }

        /// <summary>
        /// Someone who remembers a better place than what they've been finding lately may propose
        /// moving there. Each adult weighs it: their own memory of the place if they have one,
        /// otherwise how much they trust whoever proposed it. Influence decides.
        /// </summary>
        public void ConsiderMoving(Person proposer)
        {
            if (proposer.LastProposalDay == Clock.Day || !Band.Members.Contains(proposer) || proposer.AgeYears(Clock) < 18) return;
            proposer.LastProposalDay = Clock.Day;
            proposer.Restless = false;
            var memory = proposer.Places[(int)Clock.Season];
            if (memory.Count == 0) { ConsiderSplitting(proposer); return; }
            double local = LocalValue(proposer);
            int bestKey = -1; double bestValue = 0;
            foreach (var kv in memory)
            {
                var (x, y) = Person.FromPlaceKey(kv.Key);
                double d = WorldMap.Distance(x, y, Band.CampX, Band.CampY);
                if (d < WorldMap.FromMeters(1500)) continue;
                double v = kv.Value - d * WorldMap.CellMeters / 1000 * 0.015;
                if (v > bestValue) { bestValue = v; bestKey = kv.Key; }
            }
            // The gain has to outweigh the effort of moving.
            if (bestKey < 0 || bestValue - local <= 0.1 + 0.3 * StayPull) { ConsiderSplitting(proposer); return; }

            double yes = 0, no = 0;
            foreach (var a in Band.Members.Where(m => m.AgeYears(Clock) >= 16))
            {
                double mine = LocalValue(a);
                double trust = a == proposer ? 1 : Inheritance.Clamp01(a.GetAffinity(proposer) * (0.5 + proposer.M(MindTrait.Charisma)));
                double theirs = a.Places[(int)Clock.Season].TryGetValue(bestKey, out var known) ? known : mine + (bestValue - mine) * trust;
                double weight = 0.5 + a.M(MindTrait.Charisma) + a.Prestige * 0.3 + a.AgeYears(Clock) / 60;
                if (theirs - mine > 0.05 + 0.3 * StayPull) yes += weight; else no += weight;
            }
            if (yes <= no) { ConsiderSplitting(proposer); return; }

            var (tx, ty) = Person.FromPlaceKey(bestKey);
            double ddx = tx - Band.CampX, ddy = ty - Band.CampY;
            string dir = Math.Abs(ddx) > Math.Abs(ddy) ? (ddx > 0 ? "east" : "west") : (ddy > 0 ? "south" : "north");
            Band.CampX = tx; Band.CampY = ty;
            _campSince = Clock.Day;
            Band.Filth = 0;
            RefreshForagePatches();
            Chronicle.Write(Clock, Importance.Notable, $"On {proposer.Name}'s urging, the band moved camp {dir}, to the {World[tx, ty].Terrain.ToString().ToLower()}.");
        }

        bool Between(Person p, double min, double max) { var age = p.AgeYears(Clock); return age >= min && age <= max; }

        /// <summary>How attractive the band's culture finds this person.</summary>
        public double Attraction(Person p)
        {
            double s = 0;
            for (int i = 0; i < p.Mind.Length; i++) s += Band.AttractionMind[i] * (p.Mind[i] - 0.5);
            for (int i = 0; i < p.Body.Length; i++) s += Band.AttractionBody[i] * (p.Body[i] - 0.5);
            return s + p.Prestige * 0.1;
        }

        // ---- Hunting results ------------------------------------------------------------------

        public void RecordKill(Species sp, Person killer, int partySize)
        {
            ThisYear.Kills[sp.Name] = ThisYear.Kills.TryGetValue(sp.Name, out var n) ? n + 1 : 1;

            // A band admires its successful hunters a little more each time: culture drifting.
            Band.AttractionMind[(int)MindTrait.Boldness] = Math.Min(1, Band.AttractionMind[(int)MindTrait.Boldness] + 0.002);
            Band.AttractionBody[(int)BodyTrait.Strength] = Math.Min(1, Band.AttractionBody[(int)BodyTrait.Strength] + 0.002);

            // The band hears about a big kill: a little of the daring rubs off on everyone.
            if (sp.Aggression > 0.3) BandLearns("valor", 1, p => Math.Min(1, sp.Size / 6) * 0.04);
            if (sp == Species.Mammoth)
                Chronicle.Write(Clock, Importance.Major, $"{killer.Name}'s party of {partySize} brought down a mammoth.");
            else if (_killedBefore.Add(sp) && sp != Species.Rabbit)
                Chronicle.Write(Clock, Importance.Notable, $"{killer.Name} made the band's first {sp.Name} kill in this valley.");
        }

        // ---- Threats and movement --------------------------------------------------------------

        void WolvesNearCamp()
        {
            double strength = Band.Strength(Clock);
            foreach (var pack in Ecology.Living(Species.Wolf).ToList())
            {
                if (WorldMap.Distance(pack.X, pack.Y, Band.CampX, Band.CampY) > WorldMap.FromMeters(3000) || pack.Hunger < 0.75) continue;
                double power = pack.Count * pack.Hunger * 0.8;
                if (power > strength * 0.35 && Rng.Chance(0.25))
                {
                    var exposed = Band.Members.Where(p => p.Current is Forage || p.Current is GatherFlint || p.AgeYears(Clock) < 8).ToList();
                    if (exposed.Count == 0) exposed = Band.Members.ToList();
                    var victim = Rng.Pick(exposed);
                    victim.Injury = Inheritance.Clamp01(victim.Injury + Rng.Range(0.3, 1.0));
                    pack.Hunger = 0;
                    if (victim.Injury >= 0.9) Kill(victim, "killed by wolves");
                    else Chronicle.Write(Clock, Importance.Major, $"Starving wolves attacked {victim.Name}.");
                }
                else if (!_wolvesSeenThisSeason && Rng.Chance(0.1))
                {
                    _wolvesSeenThisSeason = true;
                    Chronicle.Write(Clock, Importance.Detail, "Wolves circled the camp at night, picking at scraps.");
                }
            }
        }

        IEnumerable<Cell> ScoreCampSites(int samples)
        {
            var list = new List<Cell>();
            for (int i = 0; i < samples * 4 && list.Count < samples; i++)
            {
                var c = World[Rng.Range(0, World.Size), Rng.Range(0, World.Size)];
                if (c.Terrain == Terrain.Forest || c.Terrain == Terrain.Grassland) list.Add(c);
            }
            return list.OrderByDescending(c => CampScore(c.X, c.Y));
        }

        double CampScore(double x, double y)
        {
            double plants = World.Around(x, y, WorldMap.FromMeters(3000)).Sum(c => c.PlantStock);
            double game = Ecology.Groups.Where(g => !g.Gone && g.Species.Huntable && WorldMap.Distance(g.X, g.Y, x, y) < WorldMap.FromMeters(5000))
                .Sum(g => g.Count * g.Species.Meat * 0.1);
            double water = World.Around(x, y, WorldMap.FromMeters(1000)).Any(c => c.Terrain == Terrain.River) ? 1.2 : 0.8;
            return (plants + game) * water;
        }

        void RefreshForagePatches()
        {
            ForagePatches.Clear();
            ForagePatches.AddRange(World.Around(Band.CampX, Band.CampY, WorldMap.FromMeters(4000))
                .Where(c => c.PlantStock > 0.3)
                .OrderByDescending(c => c.PlantStock / (1 + WorldMap.Distance(c.X, c.Y, Band.CampX, Band.CampY) * WorldMap.CellMeters / 1000 * 0.3))
                .Take(25));
        }

        void ReportHunger()
        {
            if (_hungerReportedThisSeason || Band.Members.Count == 0) return;
            if (Band.Members.Average(p => p.Satiety) < 0.4)
            {
                _hungerReportedThisSeason = true;
                Chronicle.Write(Clock, Importance.Major, "Hunger gripped the band.");
            }
        }

        void EndYear()
        {
            ThisYear.Population = Band.Members.Count;
            ThisYear.Couples = Band.Members.Count(m => m.Sex == Sex.Female && m.Partner != null);
            var adults = Band.Members.Where(m => m.AgeYears(Clock) >= 16).ToList();
            if (adults.Count > 0)
            {
                ThisYear.Valor = adults.Average(m => m.Expect.Get(Expectations.Norm("valor"), 0.4));
                ThisYear.Sharing = adults.Average(m => m.Expect.Get(Expectations.Norm("sharing"), 0.6));
            }
            if (ThisYear.Samples > 0) { ThisYear.AvgSatiety /= ThisYear.Samples; ThisYear.AvgHealth /= ThisYear.Samples; }
            if (Environment.GetEnvironmentVariable("ANTHRO_DEBUG_HOMES") != null)
                foreach (var h in Band.Households.Where(h => !h.Adults(Clock).Any()))
                    Console.Error.WriteLine($"NOADULT Y{Clock.Year} household {h.Id}: " + string.Join(", ", h.Members.Select(m => $"{m.Name} {m.AgeYears(Clock):F1} mother {(m.Mother == null ? "-" : m.Mother.Alive ? (Band.Members.Contains(m.Mother) ? "here" : "away") : "dead")} father {(m.Father == null ? "-" : m.Father.Alive ? (Band.Members.Contains(m.Father) ? "here" : "away") : "dead")}")));
            if (Environment.GetEnvironmentVariable("ANTHRO_DEBUG_MEMBERS") != null)
                foreach (var m in Band.Members)
                    Console.Error.WriteLine($"MEMBER Y{Clock.Year} {m.Name} age {m.AgeYears(Clock):F1} health {m.Health:F2} reserve {m.Reserve:F2} sat {m.Satiety:F2} stomach {m.Stomach:F2} home {(m.Home == null ? "-" : m.Home.Members.Count.ToString())} food {m.Home?.Food.Total ?? 0:F1} doing {m.Current} discontent {m.Discontent:F2}");
            YearEnded?.Invoke(ThisYear);
            ThisYear = new YearStats { Year = Clock.Year };
            World.Climate.NewYear(Rng);
        }
    }
}

