def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:120])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

def cut(p, start, end, replacement=''):
    """Remove from the line containing `start` up to (not including) the line containing `end`."""
    s = open(p, encoding='utf-8').read()
    i = s.index(start)
    i = s.rfind('\n', 0, i) + 1
    j = s.index(end, i)
    j = s.rfind('\n', 0, j) + 1
    s = s[:i] + replacement + s[j:]
    open(p, 'w', encoding='utf-8').write(s)

