{
    P.X = sim.Band.CampX; P.Y = sim.Band.CampY;
    var home = sim.HomeOf(P);
    home.Food.Stored += _storable;
    sim.ThisYear.Gathered += _gathered;
    home.Food.Plants += _gathered - _storable;
