        {
            if (p.Sex != Sex.Female || p.DueDay >= 0 || p.Partner == null || !p.Partner.Alive) return;
            double age = p.AgeYears(Clock);
            if (age < 16 || age > 42 || p.Satiety < 0.5) return;
            if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 2)) return;
            if (Rng.Chance(0.12 / 30 * p.Health)) { p.DueDay = Clock.Day + 270; p.ExpectingWith = p.Partner; }
        }'''
assert a in s
s=s.replace(a,'''        /// <summary>
        /// Whether a couple conceives today. Ovulation follows the mother's energy balance: well-fed
        /// women conceive readily, thin ones rarely (this is how lean times lower births among real
        /// foragers). Nursing suppresses it, strongly at first and fading as the child weans over its
        /// second and third years, which spaces births three to four years apart.
        /// </summary>
        void MaybeConceive(Person p)
        {
            if (p.Sex != Sex.Female || p.DueDay >= 0 || p.Partner == null || !p.Partner.Alive) return;
            double age = p.AgeYears(Clock);
            if (age < 16 || age > 45) return;
            // Fertility peaks in the mid-twenties and falls off toward the mid-forties.
            double byAge = age < 20 ? 0.6 + 0.1 * (age - 16) : age < 30 ? 1 : Math.Max(0, 1 - (age - 30) / 15);
            double condition = Math.Pow(p.Satiety, 3);
            var youngest = p.Children.Where(c => c.Alive).Select(c => c.AgeYears(Clock)).DefaultIfEmpty(99).Min();
            double nursing = youngest < 3 ? Math.Min(1, youngest / 3) * Math.Min(1, youngest / 3) : 1;
            if (Rng.Chance(0.12 / 30 * byAge * condition * nursing * p.Health)) { p.DueDay = Clock.Day + 270; p.ExpectingWith = p.Partner; }
        }''',1)
open(p,'w',encoding='utf-8').write(s)
EOF
