static double Norm(Person p, string name, double fallback) => p.Expect.Get(Expectations.Norm(name), fallback);

/// <summary>How fond / trusting someone is of a household, on average over its adults.</summary>
double FondOf(Person p, Household h) { var a = h.Adults(Clock).ToList(); return a.Count == 0 ? 0 : a.Average(x => p.GetAffinity(x)); }
double TrustOf(Person p, Household h) { var a = h.Adults(Clock).ToList(); return a.Count == 0 ? 0.5 : a.Average(x => p.GetTrust(x)); }

/// <summary>How hungry a household is: its people's nourishment.</summary>
static double HungerOf(Household h) => h.Members.Count == 0 ? 0 : 1 - h.Members.Average(m => m.Satiety);

/// <summary>
/// Desperation, a cold heart, a band that doesn't hold sharing sacred, nerve, and a restless
/// culture may lead someone to take food. Who they take from follows their relationships:
/// never kin, rarely people they're fond of, most readily a family they distrust that
/// turned them away while sitting on plenty. A busy camp deters it.
/// Returns how much was taken into the thief's household.
/// </summary>
public double ConsiderTheft(Person thief, double amount)
{
    if (thief.LastTheftThoughtDay == Clock.Day) return 0;
    thief.LastTheftThoughtDay = Clock.Day;
    // Real desperation: the body's reserves running out, not a skipped meal.
    double desperate = 1 - thief.Satiety;
    if (desperate < 0.4) return 0;

    var home = HomeOf(thief);
    var victim = Band.Households
        .Where(h => h != home && h.Food.Total > 1 && !h.Members.Any(m => m.IsKin(thief)))
        .OrderByDescending(h => h.DaysOfFood * (1 - FondOf(thief, h)) * (1.5 - TrustOf(thief, h)))
        .FirstOrDefault();
    if (victim == null) return 0;

    double resentment = Math.Max(0, 0.5 - TrustOf(thief, victim)) * 2;
    double propensity = desperate * (1 - thief.M(MindTrait.Warmth)) * (1.2 - Norm(thief, "sharing", 0.6))
                        * (0.4 + thief.M(MindTrait.Boldness) * 0.6) * (1 - FondOf(thief, victim)) * (1 + resentment)
                        * (1.3 - Norm(thief, "peace", 0.6));
    int watching = Band.Members.Count(m => m != thief && m.Home != home && m.AgeYears(Clock) >= 10 && AtCamp(m) && !(m.Current is Sleep));
    double seen = 1 - Math.Pow(0.85, watching);
    if (!Rng.Chance(propensity * 0.3 * (1 - seen * 0.8))) return 0;

    double took = Math.Min(amount, victim.Food.Total * 0.3);
    MoveFood(victim, home, took, out _);
    ThisYear.Thefts++;
    if (!Rng.Chance(seen)) return took;

    // How big a deal it is: how much was taken against the family's needs, how hungry they
    // already were, and how hard the times are.
    double perDay = Math.Max(0.5, victim.Members.Count * 0.9);
    double severity = Math.Min(4, (0.5 + took / perDay) * (1 + HungerOf(victim)) * (1 + _hardship));

    var wronged = victim.Adults(Clock).ToList();
    foreach (var a in wronged)
    {
        // Betrayal by someone you were fond of cuts deepest.
        double betrayal = 1 + a.GetAffinity(thief);
        a.AddTrust(thief, -0.15 * severity * betrayal);
        a.AddAffinity(thief, -0.1 * severity * betrayal);
    }
    // Bystanders take sides by whom they're closer to.
    foreach (var o in Band.Members.Where(m => m.Home != home && !wronged.Contains(m) && m.AgeYears(Clock) >= 14))
    {
        double side = wronged.Count == 0 ? 0 : wronged.Average(w => o.GetAffinity(w)) - o.GetAffinity(thief);
        o.AddTrust(thief, -0.04 * severity * (1 + Math.Max(0, side)));
    }
    thief.Prestige = Math.Max(0, thief.Prestige - 0.1 * severity);
    var face = wronged.Where(AtCamp).OrderByDescending(a => a.M(MindTrait.Temper)).FirstOrDefault();
    Chronicle.Write(Clock, severity > 2 ? Importance.Major : Importance.Notable,
        $"{thief.Name} was caught taking food from {(face ?? wronged.FirstOrDefault())?.Name ?? "another"}'s family{(severity > 2 ? " while their own children went hungry" : "")}.");
    if (face != null)
    {
        double flare = Inheritance.Clamp01((face.M(MindTrait.Temper) + thief.M(MindTrait.Temper)) / 2 - 0.25)
                       * Math.Min(1.5, severity / 1.5) * (1.3 - Norm(face, "peace", 0.6));
        if (Rng.Chance(flare)) Fight(face, thief, "stolen food", 0.7 + severity * 0.2);
    }
    return took;
}

