patch('Society.cs',[('        static Deed? LatestWrong(Person p, Person other)','        internal static Deed? LatestWrong(Person p, Person other)'),
 ('        static bool AwakeInCamp(Person p)','        internal static bool AwakeInCamp(Person p)'),
