patch('Activities/CampActivities.cs',[('''            double shortfall = want + kidsWant - home.Food.Total;
            if (shortfall > 0.05 && (P.Stomach < 0.4 || P.Satiety < 0.7))
            {
                shortfall -= sim.AskForFood(P, shortfall);
                if (shortfall > 0.05) sim.ConsiderTheft(P, shortfall);
            }
''',''),
('''        /// <summary>
        /// A meal from the family's own store. If it's short, they ask another household, and if
        /// that fails and they're desperate, some will steal. Hungry children of the household are
        /// fed first: warm-hearted adults give them nearly everything if need be.
        /// </summary>''','''        /// <summary>
        /// A meal from the family's own store. Hungry children of the household are fed first:
        /// warm-hearted adults give them nearly everything if need be. (Asking other hearths, or
        /// taking from them, are choices of their own.)
        /// </summary>'''),
('''            _with = others.OrderByDescending(o => P.GetAffinity(o) + sim.Rng.Range(0, 0.5)''','''            // People drift toward those they like and away from those they're angry with.
            _with = others.OrderByDescending(o => P.GetAffinity(o) - P.GetGrievance(o) * 0.1 + sim.Rng.Range(0, 0.5)'''),
('''            SocialLearning.Exchange(P, _with);
