 ('            if (_killed == null && Members.Count > 0) sim.BlameFailedHunt(Leader, alive);\n','')])
patch('Simulation.cs',[('''            KnitTogether(Band.Members);
            SeedCulture(Band.Members);''','''            KnitTogether(Band.Members);
            SeedCulture(Band.Members);
            SeedSocialCulture(Band.Members);'''),
('''            mother.AddAffinity(p, 0.6); father.AddAffinity(p, 0.5);''','''            mother.AddAffinity(p, 0.6); father.AddAffinity(p, 0.5);
            InheritSocialExpectations(p, mother);''')])
# Decider: asking, taking, confronting, attacking.
patch('Activities/Decider.cs',[('''            // Going to visit another band: missing people there, or hoping to find a partner.''','''            // When the hearth is running short: ask another hearth, or take from one. Each is weighed by
            // what this person has come to expect it brings (their own experience, what they've seen and
            // been told, the culture they grew up in), by guilt toward the people it would hurt, and,
            // for taking, by how likely they are to be seen.
            if (maturity > 0.6 && hunger > 0.3 && home.DaysOfFood < 2)
            {
                double amount = home.Members.Count * 0.9;
                int watchers = band.Members.Count(m => m != p && m.AgeYears(clock) >= 6 && Simulation.AwakeInCamp(m));
                double pSeen = 1 - Math.Pow(0.85, watchers);
                Household? askAt = null, takeAt = null;
                double bestAsk = 0, bestTake = 0;
                foreach (var h in band.Households)
                {
                    if (h == home || h.Food.Total < 1) continue;
                    var rel = sim.RelationTo(p, h);
                    var owner = h.Adults(clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
                    double guilt = owner == null ? 0 : Simulation.Guilt(p, owner);
                    double plenty = Math.Min(1, Simulation.Spare(h) / amount);
                    double ask = Simulation.Expects(p, Act.Ask, rel) * plenty;
                    double take = pSeen * Simulation.Expects(p, Act.Take, rel, true) + (1 - pSeen) * Simulation.Expects(p, Act.Take, rel, false) - guilt;
                    if (ask > bestAsk) { bestAsk = ask; askAt = h; }
                    if (take > bestTake) { bestTake = take; takeAt = h; }
                }
                double drive = 0.25 + hunger * 1.5;
                if (askAt != null) { var at = askAt; options.Add(new Option(Verb.Ask, drive * bestAsk / Reference * 0.5, () => new AskFor(p, at, amount))); }
                if (takeAt != null) { var at = takeAt; options.Add(new Option(Verb.Take, drive * bestTake / Reference * 0.5 * (1.3 - p.M(MindTrait.Warmth) * 0.6), () => new TakeFrom(p, at, amount))); }
            }

            // Anger at someone in camp: face them over it, or go for them. Anger is innate; what
            // confronting or hitting brings is learned.
            if (maturity > 0.7 && p.Grievance.Count > 0)
            {
                Person? target = null;
                double anger = 0;
                foreach (var o in band.Members)
                {
                    double g = p.GetGrievance(o);
                    if (g > anger && o != p && Simulation.AwakeInCamp(o)) { anger = g; target = o; }
                }
                if (target != null && anger > 0.5)
                {
                    var rel = sim.RelationTo(p, target);
                    double heat = anger / (anger + 3);
                    double guilt = Simulation.Guilt(p, target) / 10;
                    double confront = heat * (0.4 + p.M(MindTrait.Temper) * 0.6) * (1 + Simulation.Expects(p, Act.Confront, rel) / 3) - guilt;
                    double fear = Math.Max(0, target.B(BodyTrait.Strength) - p.B(BodyTrait.Strength)) * 0.5 + p.Injury;
                    double attack = heat * p.M(MindTrait.Temper) * (1 + Simulation.Expects(p, Act.Attack, rel) / 5) - guilt - fear
                                    - p.Expect.Get(Expectations.Norm("peace"), 0.6) * 0.3;
                    var t = target;
                    if (confront > 0) options.Add(new Option(Verb.Confront, confront, () => new Confront(p, t)));
                    if (attack > 0) options.Add(new Option(Verb.Attack, attack, () => new Assault(p, t)));
                }
            }

            // Going to visit another band: missing people there, or hoping to find a partner.'''),
('''                                 || o.Verb == Verb.Cook || o.Verb == Verb.GatherWood || o.Verb == Verb.Preserve;''','''                                 || o.Verb == Verb.Cook || o.Verb == Verb.GatherWood || o.Verb == Verb.Preserve
                                 || o.Verb == Verb.Ask || o.Verb == Verb.Take;'''),
])
print('ok')
