using System.Collections.Generic;
using System.Linq;

namespace Anthro.Sim.Discovery
{
    /// <summary>One condition row on a stage. With <see cref="Any"/>, one ref is enough; otherwise all are needed.</summary>
    public sealed class Need
    {
        public string Type = "";
        public string Text = "";
        public List<string> Refs = new List<string>();
        public bool Any;

        /// <summary>"Helps" rows make a stage likelier but aren't required.</summary>
        public bool IsRequired => Type != "Helps";
    }

    public sealed class Stage
    {
        public string Id = "";
        public string Name = "";
        public string Short = "";
        public bool Known;
        public string? Variant;
        public string Does = "";
        public string? Accident;
        public List<Need> Needs = new List<Need>();
        public SkillTile Tile = null!;
    }

    public sealed class SkillTile
    {
        public string Id = "";
        public string Name = "";
        public string Kind = "";
        public string Summary = "";
        public List<Stage> Stages = new List<Stage>();
    }

    /// <summary>
    /// The discovery web, loaded from docs/discovery-web.json. The sim has no JSON dependency;
    /// the runner (or Unity) parses the file and hands the tiles in.
    /// </summary>
    public sealed class DiscoveryWeb
    {
        public readonly IReadOnlyList<SkillTile> Tiles;
        public readonly IReadOnlyDictionary<string, Stage> Stages;

        public DiscoveryWeb(IEnumerable<SkillTile> tiles)
        {
            Tiles = tiles.ToList();
            var index = new Dictionary<string, Stage>();
            foreach (var t in Tiles)
                foreach (var s in t.Stages)
                {
                    s.Tile = t;
                    index[s.Id] = s;
                }
            Stages = index;
        }

        public IEnumerable<Stage> KnownAtStart => Stages.Values.Where(s => s.Known);

        /// <summary>Problems in the data: refs to stages that don't exist.</summary>
        public IEnumerable<string> Validate() =>
            from s in Stages.Values
            from n in s.Needs
            from r in n.Refs
            where !Stages.ContainsKey(r)
            select $"{s.Id} refers to unknown stage {r}";
    }
}
using System.Text.Json;
using Anthro.Sim.Discovery;

namespace Anthro.Runner;

/// <summary>Reads docs/discovery-web.json into the sim's data model.</summary>
public static class WebLoader
{
    sealed class FileDto { public List<TileDto> Tiles { get; set; } = new(); }
    sealed class TileDto
    {
        public string Id { get; set; } = "";
        public string Name { get; set; } = "";
        public string Kind { get; set; } = "";
        public string Sum { get; set; } = "";
        public List<StageDto> Stages { get; set; } = new();
    }
    sealed class StageDto
    {
        public string Id { get; set; } = "";
        public string Name { get; set; } = "";
        public string Short { get; set; } = "";
        public bool Known { get; set; }
        public string? Variant { get; set; }
        public string Does { get; set; } = "";
        public string? Accident { get; set; }
        public List<NeedDto> Needs { get; set; } = new();
    }
    sealed class NeedDto
    {
        public string T { get; set; } = "";
        public string Text { get; set; } = "";
        public List<string> Refs { get; set; } = new();
        public bool Any { get; set; }
    }

    public static DiscoveryWeb Load(string path)
    {
        var dto = JsonSerializer.Deserialize<FileDto>(File.ReadAllText(path), new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
                  ?? throw new InvalidDataException($"Could not read {path}");
        var tiles = dto.Tiles.Select(t => new SkillTile
        {
            Id = t.Id, Name = t.Name, Kind = t.Kind, Summary = t.Sum,
            Stages = t.Stages.Select(s => new Stage
            {
                Id = s.Id, Name = s.Name, Short = s.Short, Known = s.Known, Variant = s.Variant, Does = s.Does, Accident = s.Accident,
                Needs = s.Needs.Select(n => new Need { Type = n.T, Text = n.Text, Refs = n.Refs, Any = n.Any }).ToList(),
            }).ToList(),
        });
        return new DiscoveryWeb(tiles);
    }

    /// <summary>Walks up from the app folder to find docs/discovery-web.json in the repo.</summary>
    public static string? Find()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir != null; dir = dir.Parent)
        {
            var candidate = Path.Combine(dir.FullName, "docs", "discovery-web.json");
            if (File.Exists(candidate)) return candidate;
        }
        return null;
    }
}
