                if (Rng.Chance(DiscoveryRate * r.Rate * push * who * accident)) { Discover(p, s); return; }
            }
        }

        void Discover(Person p, Stage s)
        {
            p.Knows.Add(s.Id);
            bool firstAnywhere = !Region.People.Any(o => o != p && o.Knows.Contains(s.Id));
            string how = s.Accident != null && Rng.Chance(0.5) ? $" ({s.Accident.TrimEnd('.')}.)" : "";
            Chronicle.Write(Clock, Importance.Major, $"{p.Name} worked out {s.Name.ToLowerInvariant()}.{how}");
            if (firstAnywhere) Region.Chronicle.Write(Clock, Importance.Notable, $"The {Band.Name} band were the first anyone knows of to have {s.Name.ToLowerInvariant()}.");
            Region.DiscoveryLog.Add((Clock.Year, Band.Name, s.Id));
        }

        /// <summary>
        /// Showing and telling: in talk, or a child watching someone work, a person may pass on one
        /// thing they know that the other is ready to learn. Good teachers and apt learners pass on more.
        /// </summary>
        public void PassOn(Person teacher, Person learner, double strength = 1)
        {
            if (Web == null || learner.AgeYears(Clock) < 4) return;
            Stage? pick = null;
            int seen = 0;
            foreach (var id in teacher.Knows)
            {
                if (learner.Knows.Contains(id) || !Web.Stages.TryGetValue(id, out var s) || s.Known) continue;
                if (!DiscoveryWeb.CanLearn(s, learner.Knows)) continue;
                if (Rng.Range(0, ++seen) == 0) pick = s;
            }
            if (pick == null) return;
            double chance = 0.08 * strength * (0.3 + teacher.S(Skill.Teaching)) * Lean(learner.M(MindTrait.Aptitude));
            if (!Rng.Chance(chance)) return;
            bool newToBand = !Band.AnyoneKnows(pick.Id);
            learner.Knows.Add(pick.Id);
            teacher.Practice(Skill.Teaching, 1);
            var teacherBand = Region.BandOf(teacher);
            if (newToBand && teacherBand != null && teacherBand != this)
                Chronicle.Write(Clock, Importance.Major, $"{learner.Name} learned {pick.Name.ToLowerInvariant()} from {teacher.Name} of the {teacherBand.Band.Name} band.");
            else
                Chronicle.Write(Clock, Importance.Detail, $"{teacher.Name} showed {learner.Name} {pick.Name.ToLowerInvariant()}.");
        }
    }
}

