            Learn(taker, deed.Context, took, CulturalDefault(Act.Take, rel, seen.Count > 0));
            // Those who saw it also saw what it got the taker.
            foreach (var w in seen)
                if (w.Alive) w.Expect.Absorb(deed.Context, took, 0.05 * (0.5 + w.M(MindTrait.Openness)), w.Expect.Get(deed.Context, CulturalDefault(Act.Take, rel, true)));
            // Seen taking from your own hearth, or from someone you're close to: answer it now, or let it go.
            Person? answer = null;
            double best = 0;
