                                   - (owner == null ? 0 : Simulation.Guilt(p, owner)) / 10;
                        if (v > best) { best = v; target = h; }
                    }
                    if (target != null) { var t = target; options.Add(new Option(Verb.Rally, best, () => new Rally(p, t))); }
                }
            }
