patch('JointActs.cs', [
    ('''        /// <summary>
        /// Should this person join a group going to take a household's food by force?
        /// </summary>
        double WantsToJoinRaid(Person p, Person leader, Household hearth)
        {
            if (p.Home == hearth || p.AgeYears(Clock) < 16 || p.Health < 0.4 || !AwakeInCamp(p)) return -1;
            var rel = RelationTo(p, hearth);
            var owner = hearth.Adults(Clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
            double hunger = 1 - (p.Home?.Members.Select(m => m.Satiety).DefaultIfEmpty(1).Min() ?? p.Satiety);
            double plenty = Math.Min(1, Spare(hearth) / Math.Max(1, (p.Home?.Members.Count ?? 1) * 2));
            double anger = AngerAt(p, hearth);
            return hunger * plenty * 1.5 + anger / (anger + 3)
                   + p.GetAffinity(leader) * 0.5 + (p.GetTrust(leader) - 0.5)
                   + Expects(p, Act.Take, rel, true) / 5
