            // easier for skilled trackers (and with dogs).
            double skill = alive.Average(m => m.S(Skill.Hunting)) + (sim.Band.AnyoneKnows("dog.hunt") ? 0.2 : 0);
            double drift = WorldMap.Distance(_believedX, _believedY, Target.X, Target.Y) * WorldMap.CellMeters / 1000;
            if (sim.Rng.Chance((0.25 + 0.5 * skill) * Math.Exp(-drift / (0.7 + 2 * skill))))
            {
                _believedX = Target.X; _believedY = Target.Y;
                foreach (var m in alive) m.Map.Sight(Target, sim.Clock.Day);
                ChooseTactic(sim, alive);
                Current = Phase.Stalk;
                return;
            }
            // Following the trail closes some of the gap.
            _believedX += (Target.X - _believedX) * 0.3 * skill;
            _believedY += (Target.Y - _believedY) * 0.3 * skill;
            if (!KeepGoing(sim, alive, 0.5)) GoBack();'''),
    # Tactics at the approach.
    ('''            double approach = Math.Max(0.02, Math.Max(creep, drive));
            if (sim.Rng.Chance(approach)) { Current = Phase.Strike; return; }''',
     '''            double fear = Target.Fear;
            double patience = alive.Average(m => m.M(MindTrait.Patience));
            double approach = Tactic switch
            {
                Tactic.Drive => drive,
                Tactic.Ambush => 0.25 * patience * (1 - 0.6 * fear),
                Tactic.Surround => 0.35 * Math.Min(1, (alive.Count - 2) / 6.0) * (0.5 + skill) * (1 - 0.3 * fear),
                Tactic.Persistence => 0.3 * alive.Average(m => m.B(BodyTrait.Endurance)) * (sim.Clock.Season == Core.Season.Summer ? 1 : 0.4),
                Tactic.FireDrive => 0.5,
                _ => creep,
            };
            if (sim.Rng.Chance(Math.Max(0.02, approach))) { Current = Phase.Strike; return; }
            // Waiting in ambush doesn't spook them; they can wait some hours yet.
