398	        /// <summary>Rations a day this person needs: by age and size, more when pregnant or nursing.</summary>
399	        public double DailyNeed(Person p)
400	        {
401	            double age = p.AgeYears(Clock);
402	            if (age < 1) return 0;
403	            double need = age < 2 ? 0.1 : age < 14 ? 0.2 + 0.3 * age / 14 : 0.5;
404	            if (p.DueDay >= 0) need += 0.1;
405	            if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 2)) need += 0.15;
406	            // Bigger bodies eat more; so does a strong immune system, which is why immunity doesn't simply max out.
407	            return need * 2 * (0.85 + 0.3 * p.B(BodyTrait.Build) * p.B(BodyTrait.Height)) * (1 + 0.15 * (p.B(BodyTrait.Immunity) - 0.5));
408	        }
