410	        /// <summary>
411	        /// A day in a body. Each harm is booked against its cause, so a death is always explained
412	        /// by what actually wore the person down.
413	        /// </summary>
414	        void DailyBody(Person p, double temp)
415	        {
416	            double age = p.AgeYears(Clock);
417	            // Each harm is booked against its cause in a ledger that fades over a few weeks, so a death
418	            // is attributed to whatever really wore the person down, not just the last day's blow.
419	            foreach (var key in p.HarmLedger.Keys.ToList()) p.HarmLedger[key] *= 0.93;
420	            var harm = p.HarmLedger;
421	            void Hurt(string cause, double amount)
422	            {
423	                if (amount <= 0) return;
424	                p.Health -= amount;
425	                harm[cause] = (harm.TryGetValue(cause, out var h) ? h : 0) + amount;
426	            }
427	
428	            // Outright starvation only when the body's reserves are all but gone. Before that,
429	            // short rations do their damage by weakening people against sickness.
430	            // Wasting does its damage while the body is going without, not while someone thin is eating again.
431	            if (p.Satiety < 0.15 && p.Stomach < 0.3) Hurt("starvation", (0.15 - p.Satiety) * 0.2);
432	            // Going hungry makes people care more about food; a wound, more about safety.
433	            if (p.Satiety < 0.4) p.Shift(Drive.Food, 0.0005);
434	            if (p.Injury > 0.3) p.Shift(Drive.Safety, 0.0005);
435	            // Over months, people settle back toward who they are.
436	            for (int i = 0; i < p.Drives.Length; i++) p.Drives[i] += (p.BaseDrives[i] - p.Drives[i]) * 0.003;
437	
438	            double cold = Math.Max(0, (Shelter.ComfortTemp(Band, p) - temp) / 20.0 - p.B(BodyTrait.ColdTolerance) * 0.3 - p.B(BodyTrait.Build) * 0.1);
439	            if (age < 5 || age > 60) cold *= 1.5;
440	            // Sleeping close to family shares body heat; small children sleep against their parents.
441	            if (HasSleepingFamily(p)) cold *= 0.6;
442	            p.ColdStress = cold;
443	            // Cold mostly kills by weakening people against sickness; it freezes outright only when severe.
444	            Hurt("cold", Math.Max(0, cold - 0.3) * 0.05);
445	
446	            Infection(p, age, cold);
447	            if (p.Illness != null)
448	            {
449	                // The body's response builds over the days of a sickness, so most illnesses peak and pass.
450	                var d = p.Illness;
451	                p.SickDays++;
452	                // Care and rest help the body fight; they can't fight for it.
453	                double fight = Physiology.ImmuneStrength(p, age) * 0.08 * (1 + p.SickDays * 0.15)
454	                               * (1 + 0.5 * Math.Min(4, p.CareToday) / 4 + (p.Current is Rest || p.Current is Sleep ? 0.25 : 0));
455	                p.Sickness += d.Growth * (age < 5 ? d.ChildRisk : 1) - fight;
456	                if (p.Sickness <= 0)
457	                {
458	                    p.Sickness = 0; p.Illness = null; p.SickDays = 0;
459	                    if (d.ImmunityGain > 0) p.Immunities[d] = Math.Max(p.ImmunityTo(d), d.ImmunityGain);
460	                }
461	                else Hurt(d.DiedOf, p.Sickness * d.Harm * (age < 5 ? d.ChildRisk : 1));
462	            }
463	            foreach (var d in p.Immunities.Keys.ToList()) p.Immunities[d] = Math.Max(0, p.Immunities[d] - d.ImmunityFade);
464	
465	            p.Injury = Math.Max(0, p.Injury - 0.01 * (0.5 + p.B(BodyTrait.Endurance)));
466	            if (p.Satiety >= 0.35 && p.Sickness == 0) p.Health += 0.01 * (age > 50 ? 0.6 : 1);
467	            p.Health = Math.Min(p.Health, Physiology.MaxHealth(age) - p.Injury * 0.5);
468	
469	            // People remember the worst of the lean months (winter into spring, until the land greens),
470	            // not the average. The memory spreads like any belief and drives autumn stockpiling.
471	            if (Clock.Season == Season.Winter || Clock.Season == Season.Spring) p.WinterLow = Math.Min(p.WinterLow, p.Satiety);
472	            if (Clock.Season == Season.Summer && Clock.DayOfSeason == 20 && age >= 10)
473	            {
474	                // A hard lean season is unforgettable: the lesson lands at once, hardest on the less resilient.
475	                p.Expect.Absorb("lean:season", 1 - p.WinterLow, 0.3 + 0.3 * (1 - p.M(MindTrait.Resilience)), 0.2);
476	                p.WinterLow = 1;
477	            }
478	
479	            p.CareToday = 0;
480	            p.Fatigue *= 0.9;
481	            if (!p.Restless && age >= 20 && Rng.Chance(Crowding(p) * 0.02)) p.Restless = true;
482	            if (age < 12) DriftTowardParents(p);
483	
484	            if (p.Health > 0) return;
485	            string cause = harm.Count == 0 ? (p.Injury > 0.5 ? "wounds" : "old age") : harm.OrderByDescending(kv => kv.Value).First().Key;
486	            var weakened = new List<string>();
487	            if (Environment.GetEnvironmentVariable("ANTHRO_DEBUG_DEATHS") != null)
488	                Console.Error.WriteLine($"DEATH {p.Name} age {age:F1} {Clock.Season} cause {cause} | ledger {string.Join(", ", harm.Select(kv => $"{kv.Key} {kv.Value:F2}"))} | reserve {p.Reserve:F2} stomach {p.Stomach:F2} home food {p.Home?.Food.Total ?? 0:F1} camp food {Band.FoodTotal:F0} for {Band.Members.Count} | sick {p.Illness?.Name ?? "-"} | doing {p.Current} | expect forage {p.Expect.Get(Verb.Forage, 0):F2} hunt {p.Expect.Get(Verb.Hunt, 0):F2} | home size {p.Home?.Members.Count ?? 0} fuel {p.Home?.Fuel ?? 0:F1}");
489	            if (cause != "starvation" && p.Satiety < 0.5) weakened.Add("hunger");
490	            if (cause != "cold" && p.ColdStress > 0.15) weakened.Add("cold");
491	            if (Physiology.MaxHealth(age) < 0.3 && cause != "old age") weakened.Add("age");
492	            Kill(p, cause, weakened.Count == 0 ? null : "weakened by " + string.Join(" and ", weakened));
493	        }
