495	        /// <summary>
496	        /// Sickness always comes from somewhere that isn't another person: a fouled camp, rotten
497	        /// meat, an open wound, or (for someone already sick) a winter chill settling in the lungs.
498	        /// Catching diseases from people happens through <see cref="Contact"/>.
499	        /// </summary>
500	        /// <summary>
501	        /// Calibration (fitted to forager child mortality, ~20% before 1 and ~45% before 15): the
502	        /// daily chance a sickness settles in the chest before cold is counted, and how much likelier
503	        /// gut infections are in the weaning years.
504	        /// </summary>
505	        public static double ChestRisk = 0.005, WeaningRisk = 6;
506	
507	        /// <summary>
508	        /// Calibration (fitted to forager mortality: accidents ~5-10% of deaths, ~1-2 adult deaths
509	        /// per 1,000 a year): chance per hour out on the land of a serious accident.
510	        /// </summary>
511	        public static double AccidentRate = 1e-5;
512	
513	        /// <summary>
514	        /// Out on the land, things go wrong now and then: a fall, a bad cut, a slip into cold water.
515	        /// Most are wounds that heal (or fester); some kill.
516	        /// </summary>
517	        void MaybeAccident(Person p)
518	        {
519	            var a = p.Current;
520	            bool water = a is Fish;
521	            if (!(a is Forage || a is Hunt || a is Fish || a is Trap || a is GatherWood || a is GatherFlint || a is Visit)) return;
522	            if (!Rng.Chance(AccidentRate * (a is Hunt ? 2 : 1))) return;
523	            p.Injury = Inheritance.Clamp01(p.Injury + Rng.Range(0.3, 1.2));
524	            if (p.Injury >= 0.95) Kill(p, water ? "drowning" : "a fall");
525	            else Chronicle.Write(Clock, Importance.Detail, $"{p.Name} was badly hurt in {(water ? "the river" : "a fall")}.");
526	        }
