528	        /// <summary>Calibration: daily chance of catching a fever from insects or water (warm-season peak).</summary>
529	        public static double FeverRate = 0.0003;
530	
531	        void Infection(Person p, double age, double coldStress)
532	        {
533	            double immune = Physiology.ImmuneStrength(p, age);
534	            // A breastfed baby in its first months carries its mother's protection, from her milk.
535	            var mother = p.Mother;
536	            bool nursed = age < 0.5 && mother != null && mother.Alive && Band.Members.Contains(mother);
537	            double Protected(Disease d) => Math.Max(p.ImmunityTo(d), nursed ? mother!.ImmunityTo(d) * 0.8 : 0);
538	            if (p.Illness != null)
539	            {
540	                // Another sickness can settle in the lungs: most often in babies and the old, and far
541	                // more when they're chilled. What winter kills the old with, and small children all year.
542	                double frail = age < 2 ? 3 : age < 5 ? 1.5 : age > 60 ? 2 : 1;
543	                if (p.Illness != Disease.LungSickness && Rng.Chance((ChestRisk + coldStress * 0.05) * frail * (1.3 - immune)))
544	                {
545	                    p.Illness = Disease.LungSickness;
546	                    p.Sickness = Math.Max(p.Sickness, 0.3);
547	                    p.SickDays = 0;
548	                }
549	                return;
550	            }
551	            double weak = 1.3 - immune;
552	            // Colds are always around in any human group, and spread more when people huddle in winter.
553	            double coldSeason = Clock.Season == Season.Winter ? 3 : Clock.Season == Season.Autumn ? 1.5 : 1;
554	            // Small children catch everything going: their bodies haven't met these germs yet.
555	            double young = age < 5 ? 2.5 : age < 14 ? 1.5 : 1;
556	            if (Rng.Chance(0.004 * coldSeason * young * weak * (1 - Protected(Disease.Cold)))) { p.Catch(Disease.Cold, Rng.Range(0.1, 0.3)); return; }
557	            // Gut infections are always around for small children, from dirt and, worst of all, from
558	            // the first foods other than milk: the weaning years are the most dangerous of childhood.
559	            double weaning = age >= 0.5 && age < 3 ? WeaningRisk : 1;
560	            if (age < 5 && Rng.Chance(0.0015 * weaning * weak * (1 - Protected(Disease.Flux)))) { p.Catch(Disease.Flux, Rng.Range(0.1, 0.3)); return; }
561	            // Fevers carried by insects and water turn up now and then, more in the warm months.
562	            double warm = Clock.Season == Season.Summer ? 2 : Clock.Season == Season.Winter ? 0.2 : 1;
563	            if (Rng.Chance(FeverRate * warm * young * weak * (1 - Protected(Disease.Fever)))) { p.Catch(Disease.Fever, Rng.Range(0.15, 0.35)); return; }
564	            if (p.AteRotten && Rng.Chance(0.3 * weak)) { p.Catch(Disease.BadMeat, Rng.Range(0.15, 0.35)); return; }
565	            if (p.Injury > 0.2 && Rng.Chance(p.Injury * 0.03 * weak)) { p.Catch(Disease.WoundRot, Rng.Range(0.2, 0.4)); return; }
566	            double filth = Band.Filth * 0.0004 * (age < 5 ? 2 : 1);
567	            if (Rng.Chance(filth * weak * (1 - Protected(Disease.Flux)))) p.Catch(Disease.Flux, Rng.Range(0.15, 0.4));
568	        }
