570	        /// <summary>
571	        /// Close contact between two people for some hours: a contagious illness may pass either way,
572	        /// depending on how sick the carrier is and how well the other resists.
573	        /// </summary>
574	        public void Contact(Person a, Person b, double hours)
575	        {
576	            Pass(a, b, hours);
577	            Pass(b, a, hours);
578	        }
