580	        void Pass(Person from, Person to, double hours)
581	        {
582	            var d = from.Illness;
583	            if (d == null || d.Contagion <= 0 || to.Illness != null || !to.Alive) return;
584	            double resist = Physiology.ImmuneStrength(to, to.AgeYears(Clock));
585	            double chance = d.Contagion * from.Sickness * hours * (1.3 - resist) * (1 - to.ImmunityTo(d));
586	            if (Rng.Chance(chance)) to.Catch(d, Rng.Range(0.1, 0.3));
587	        }
