592	        bool HasSleepingFamily(Person p) =>
593	            !(p.Current is Visit) &&
594	            ((p.Partner != null && Home(p.Partner))
595	            || p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 14 && Home(c))
596	            || (p.AgeYears(Clock) < 14 && ((p.Mother != null && Home(p.Mother)) || (p.Father != null && Home(p.Father)))));
