615	        /// <summary>Children's interests lean toward whoever raises them.</summary>
616	        static void DriftTowardParents(Person child)
617	        {
618	            foreach (var parent in new[] { child.Mother, child.Father })
619	            {
620	                if (parent == null || !parent.Alive) continue;
621	                for (int i = 0; i < child.Interests.Length; i++)
622	                    child.Interests[i] += (parent.Interests[i] - child.Interests[i]) * 0.002;
623	            }
624	        }
