626	        public void Kill(Person p, string cause, string? weakenedBy = null)
627	        {
628	            if (!p.Alive) return;
629	            double age = p.AgeYears(Clock);
630	            p.Alive = false;
631	            p.DeathCause = cause;
632	            p.DeathDay = Clock.Day;
633	            Band.LastDeathDay = Clock.Day;
634	            // Losing family makes people hold the rest closer.
635	            foreach (var kin in Band.Members) if (kin.IsKin(p)) kin.Shift(Drive.Family, 0.01);
636	            // Laying the dead to rest eases the grief of those left (less of it turns to discontent).
637	            if (Band.AnyoneKnows("burial.cover"))
638	                foreach (var m in Band.Members) m.Discontent *= Band.AnyoneKnows("burial.goods") ? 0.9 : 0.95;
639	            LeaveHousehold(p);
640	            Band.Members.Remove(p);
641	            Band.Dead.Add(p);
642	            if (p.Partner != null) { p.Partner.Partner = null; p.Partner = null; }
643	            ThisYear.Deaths[cause] = ThisYear.Deaths.TryGetValue(cause, out var n) ? n + 1 : 1;
644	
645	            string what = cause.StartsWith("killed") || cause.StartsWith("trampled") || cause.StartsWith("gored") ? $"was {cause}" : $"died of {cause}";
646	            WitnessDeath(p, cause);
647	            if (cause.StartsWith("starvation"))
648	            {
649	            }
650	            string who = p.BigKills >= 5 ? $"{p.Name}, one of the band's great hunters," : p.Name;
651	            Chronicle.Write(Clock, age < 5 ? Importance.Detail : Importance.Notable, $"{who} {what} at {(int)age}{(weakenedBy == null ? "" : ", " + weakenedBy)}.");
652	
653	            foreach (var stage in p.Knows)
654	                if (!Band.AnyoneKnows(stage) && Web != null && Web.Stages.TryGetValue(stage, out var s) && !s.Known)
655	                    Chronicle.Write(Clock, Importance.Major, $"When {p.Name} died, the band lost {s.Name.ToLower()}.");
656	
657	            if (Band.Members.Count == 0)
658	                Chronicle.Write(Clock, Importance.Major, $"With {p.Name}'s death, the {Band.Name} band is gone.");
659	        }
