675	        /// <summary>
676	        /// Whether a couple conceives today. Ovulation follows the mother's energy balance: well-fed
677	        /// women conceive readily, thin ones rarely (this is how lean times lower births among real
678	        /// foragers). Nursing suppresses it, strongly at first and fading as the child weans over its
679	        /// first four years, which spaces births about four years apart.
680	        /// </summary>
681	        void MaybeConceive(Person p)
682	        {
683	            if (p.Sex != Sex.Female || p.DueDay >= 0 || p.Partner == null || !p.Partner.Alive) return;
684	            double age = p.AgeYears(Clock);
685	            if (age < 16 || age > 45) return;
686	            // Fertility peaks in the mid-twenties and falls off toward the mid-forties.
687	            // Fertility is low in the late teens (forager women first give birth around 19), peaks in the
688	            // twenties, and falls off toward the mid-forties.
689	            double byAge = age < 22 ? 0.2 + 0.8 * (age - 16) / 6 : age < 30 ? 1 : Math.Max(0, 1 - (age - 30) / 15);
690	            double condition = Math.Pow(p.Satiety, 3);
691	            var youngest = p.Children.Where(c => c.Alive).Select(c => c.AgeYears(Clock)).DefaultIfEmpty(99).Min();
692	            // On-demand nursing for years keeps ovulation suppressed (forager births come ~4 years apart).
693	            double nursing = youngest < 4 ? Math.Pow(youngest / 4, 2) : 1;
694	            if (Rng.Chance(0.12 / 30 * byAge * condition * nursing * p.Health)) { p.DueDay = Clock.Day + 270; p.ExpectingWith = p.Partner; }
695	        }
