697	        void GiveBirth(Person mother)
698	        {
699	            mother.DueDay = -1;
700	            var father = mother.ExpectingWith ?? mother.Partner!;
701	            mother.ExpectingWith = null;
702	            var child = NewChild(mother, father, 0);
703	            child.Health = 0.6 + 0.4 * mother.Satiety;
704	            ThisYear.Births++;
705	            Chronicle.Write(Clock, Importance.Detail, $"{child.Name} was born to {mother.Name} and {father.Name}.");
706	
707	            // Births go wrong more often for older, weaker or hungrier mothers.
708	            double age = mother.AgeYears(Clock);
709	            double complication = 0.01 + Math.Max(0, age - 35) * 0.004 + (1 - mother.Health) * 0.05 + (1 - mother.Satiety) * 0.03;
710	            if (Rng.Chance(complication))
711	            {
712	                // Bleeding and infection after birth: about half of serious complications kill, which
713	                // comes to roughly one death per hundred births, as among real foragers.
714	                mother.Health -= Rng.Range(0.5, 1.5);
715	                if (mother.Health <= 0) Kill(mother, "childbirth");
716	                else Chronicle.Write(Clock, Importance.Notable, $"{mother.Name} barely survived giving birth to {child.Name}.");
717	            }
718	        }
