720	        /// <summary>Unpaired adults of opposite sex who aren't close kin.</summary>
721	        public bool CouldPair(Person a, Person b) =>
722	            a.Sex != b.Sex && a.Partner == null && b.Partner == null && a.Alive && b.Alive && !a.IsKin(b)
723	            && Grown(a) && Grown(b) && a.AgeYears(Clock) <= (a.Sex == Sex.Female ? 45 : 60) && b.AgeYears(Clock) <= (b.Sex == Sex.Female ? 45 : 60);
724	
725	        /// <summary>
726	        /// Two people pair. If they come from different bands, each weighs what moving would cost them
727	        /// (the people they'd leave, how each band is faring, and what both bands' customs say about
728	        /// who moves), and whoever would lose less moves.
729	        /// </summary>
730	        public void Pair(Person a, Person b)
731	        {
732	            a.Partner = b; b.Partner = a;
733	            a.PairedDay = b.PairedDay = Clock.Day;
734	            a.AddAffinity(b, 0.3); b.AddAffinity(a, 0.3);
735	            var bandA = Region.BandOf(a) ?? this;
736	            var bandB = Region.BandOf(b) ?? this;
737	            if (bandA == bandB)
738	            {
739	                bandA.NewHousehold(a, b);
740	                bandA.Chronicle.Write(Clock, Importance.Detail, $"{a.Name} and {b.Name} paired.");
741	                return;
742	            }
743	            double norm = (bandA.Band.ResidenceNorm + bandB.Band.ResidenceNorm) / 2;
744	            double Cost(Person p, Simulation own, Simulation other) =>
745	                Ties(p, own.Band.Members) - Ties(p, other.Band.Members) * 0.5 - (other.Prospects - own.Prospects) * 4
746	                - norm * (p.Sex == Sex.Female ? 1 : -1);
747	            bool aMoves = Cost(a, bandA, bandB) <= Cost(b, bandB, bandA);
748	            var mover = aMoves ? a : b;
749	            var partner = aMoves ? b : a;
750	            var from = aMoves ? bandA : bandB;
751	            var to = aMoves ? bandB : bandA;
752	            // A custom about who moves forms from what people actually do, on both sides.
753	            foreach (var band in new[] { from, to })
754	                band.Band.ResidenceNorm += ((mover.Sex == Sex.Female ? 1 : -1) - band.Band.ResidenceNorm) * 0.1;
755	            // Young children with no other parent there go with them.
756	            var kids = mover.Children.Where(c => c.Alive && c.AgeYears(Clock) < 14 && from.Band.Members.Contains(c)
757	                                                 && !(c.Mother != mover && c.Mother != null && from.Band.Members.Contains(c.Mother))
