1	using System;
2	
3	namespace Anthro.Sim.People
4	{
5	    /// <summary>
6	    /// Bodies, not dice. Nobody dies from a random roll: health falls because of hunger, cold,
7	    /// wounds, sickness or childbirth, and an aging body holds less health, so the old die of
8	    /// the same things the young survive.
9	    /// </summary>
10	    public static class Physiology
11	    {
12	        /// <summary>The most health a body can hold. Full until about 40, then a slow decline to nothing in the late 80s.</summary>
13	        public static double MaxHealth(double age) => age < 40 ? 1 : Math.Max(0, 1 - Math.Pow((age - 40) / 46.0, 2));
14	
15	        /// <summary>How grown a body is: 0 at birth, full by about 16.</summary>
16	        public static double Maturity(double age) => Math.Max(0, Math.Min(1, (age - 1) / 15));
