        double gap = (kids[i].BirthDay - kids[i - 1].BirthDay) / DPY; ibi.Add(gap);
        var prev = kids[i - 1]; if (prev.Alive || Age(prev, prev.DeathDay) > gap) ibiSurv.Add(gap);
