for (int i = 0; i < 7; i++) { double r = fExpo[i] > 0 ? fBirths[i] / fExpo[i] : 0; tfr += r * 5; Console.WriteLine($"  {fEdges[i]}-{fEdges[i + 1] - 1}  {fExpo[i],8:F0} {fBirths[i],6} {r,6:F3}"); }
