                if (g.Fear > 0.3) s -= g.Fear * Math.Max(0, 1 - NearestCamp(sim, c.X, c.Y) / WorldMap.FromMeters(3000));
                return s;
            }
            Cell best = sim.World[(int)g.X, (int)g.Y];
            double bestScore = Score(best), bestFood = Forage(sp, best, climate, season);
