using Anthro.Sim;
using Anthro.Sim.Core;
using Anthro.Sim.Ecology;
using Anthro.Sim.World;

// The land and its animals with nobody living on it: do herds hold near what the land carries,
// and do the seasons and years look right?
ulong seed = ulong.Parse(args[0]); int years = int.Parse(args[1]);
var region = Region.Create(seed);
region.Bands.Clear();
var w = region.World;
var valley = w.All().Where(c => c.Terrain != Terrain.River).OrderBy(c => c.Elevation).Take(2000).ToList();
var hills = w.All().OrderByDescending(c => c.Elevation).Take(2000).ToList();
Console.WriteLine($"elevation: valley floor {valley.Average(c => c.Elevation) * Climate.MetersPerElevation:F0} m, high ground {hills.Average(c => c.Elevation) * Climate.MetersPerElevation:F0} m");
int lastYear = region.Clock.Year;
var log = new List<string>();
double maxSnowV = 0, maxSnowH = 0; int snowDaysV = 0, snowDaysH = 0;
var minCond = new Dictionary<Species, double>();
var awayPeak = new Dictionary<Species, int>();
string leftReturned = "";
while (region.Clock.Year < years)
{
    int doy = region.Clock.DayOfYear;
    System.Threading.Tasks.Parallel.For(0, w.Size, x => { for (int y = 0; y < w.Size; y++) w.Cells[x, y].DailyRegrow(w.Climate, doy); });
    region.Ecology.DailyUpdate(region);
    double sv = valley.Average(c => c.Snow), sh = hills.Average(c => c.Snow);
    maxSnowV = Math.Max(maxSnowV, sv); maxSnowH = Math.Max(maxSnowH, sh);
    if (sv > 10) snowDaysV++; if (sh > 10) snowDaysH++;
    foreach (var sp in Species.All)
    {
        var gs = region.Ecology.Living(sp).ToList();
        if (gs.Count > 0) minCond[sp] = Math.Min(minCond.TryGetValue(sp, out var m) ? m : 1, gs.Average(g => g.Condition));
        awayPeak[sp] = Math.Max(awayPeak.TryGetValue(sp, out var a) ? a : 0, region.Ecology.Away(sp));
    }
    if (doy % 30 == 0 && region.Clock.Year < 3)
        leftReturned += $"\n  Y{region.Clock.Year} day {doy,3}: valley {w.Climate.TemperatureAt(doy, valley[0].Elevation),5:F1}C snow {sv,4:F0}cm | hills {w.Climate.TemperatureAt(doy, hills[0].Elevation),5:F1}C snow {sh,4:F0}cm | deer on map {region.Ecology.Total(Species.Deer)} away {region.Ecology.Away(Species.Deer)} cond {region.Ecology.Living(Species.Deer).Select(g => g.Condition).DefaultIfEmpty(0).Average():F2}; mammoths {region.Ecology.Total(Species.Mammoth)}/{region.Ecology.Away(Species.Mammoth)}; plants {w.All().Sum(c => c.PlantStock):F0}";
    for (int h = 0; h < SimClock.HoursPerDay; h++) region.Clock.Advance();
    if (region.Clock.Year != lastYear)
    {
        lastYear = region.Clock.Year;
        w.Climate.NewYear(region.Rng);
        foreach (var c in w.All()) c.Wet = w.Climate.Wetness(c.X, c.Y, w.Size);
        Console.WriteLine($"Y{lastYear - 1,3} winter sev {w.Climate.WinterSeverity,5:F1} | " + string.Join(" | ", Species.All.Select(sp => $"{sp.Name} {region.Ecology.Total(sp) + region.Ecology.Away(sp)} (min cond {(minCond.TryGetValue(sp, out var m) ? m : 0):F2}, away peak {awayPeak[sp]})"))
                          + $" | snow max valley {maxSnowV:F0} hills {maxSnowH:F0} cm, days>10cm {snowDaysV}/{snowDaysH}");
        maxSnowV = maxSnowH = 0; snowDaysV = snowDaysH = 0; minCond.Clear(); awayPeak.Clear();
    }
}
Console.WriteLine(leftReturned);
foreach (var e in region.Chronicle.Entries.Take(30)) Console.WriteLine($"  Y{e.Year} {e.Season} {e.Text}");

