62	        /// <summary>
63	        /// How strongly someone feels the need to put food by for winter: how lean they remember
64	        /// winters being, how patient they are, and how far short of enough the camp's keeping-food is.
65	        /// Only felt as winter approaches.
66	        /// </summary>
67	        public static double Foresight(Simulation sim, Person p)
68	        {
69	            var season = sim.Clock.Season;
70	            if (season != Season.Autumn && !(season == Season.Summer && sim.Clock.DayOfSeason > 45)) return 0;
71	            double lean = p.Expect.Get("lean:season", 0.2);
72	            var home = sim.HomeOf(p);
73	            // Enough keeping-food in their own hearth to carry them through as much of the lean months
