patch('Simulation.cs',[
("""            // People remember the worst of the lean months (winter into spring, until the land greens),
            // not the average. The memory spreads like any belief and drives autumn stockpiling.
            if (Clock.Season == Season.Winter || Clock.Season == Season.Spring) p.WinterLow = Math.Min(p.WinterLow, p.Satiety);
            if (Clock.Season == Season.Summer && Clock.DayOfSeason == 20 && age >= 10)
            {
                // A hard lean season is unforgettable: the lesson lands at once, hardest on the less resilient.
                p.Expect.Absorb("lean:season", 1 - p.WinterLow, 0.3 + 0.3 * (1 - p.M(MindTrait.Resilience)), 0.2);
                p.WinterLow = 1;
            }""",
"""            // People remember how lean each season got (the worst of it, not the average: getting thin
            // counts, not only going hungry). The memory spreads like any belief, and as a season they
            // know to be lean draws near it moves them to put food by (see Decider.Foresight).
            p.WinterLow = Math.Min(p.WinterLow, Math.Min(p.Satiety, Physiology.BodyFat(p, age) / 0.6));
            if (Clock.DayOfSeason == SimClock.DaysPerSeason - 1 && age >= 10)
            {
                // A hard season is unforgettable: the lesson lands at once, hardest on the less resilient.
                p.Expect.Absorb(LeanTopic(Clock.Season), 1 - p.WinterLow, 0.3 + 0.3 * (1 - p.M(MindTrait.Resilience)), 0.2);
                p.WinterLow = 1;
            }"""),
("""lean-season belief {Band.Members.Average(m => m.Expect.Get("lean:season", 0.2)):F2}""",
 """lean-season beliefs {string.Join("/", Enum.GetValues(typeof(Season)).Cast<Season>().Select(s => Band.Members.Average(m => m.Expect.Get(LeanTopic(s), 0.2)).ToString("F2")))}"""),
("""        /// <summary>The ground the camp stands on: its weather is the band's weather.</summary>""",
"""        static readonly string[] _leanTopics = { "lean:spring", "lean:summer", "lean:autumn", "lean:winter" };
        /// <summary>The belief "how lean does this season get" (0 = plenty, 1 = starving).</summary>
        public static string LeanTopic(Season s) => _leanTopics[(int)s];

        /// <summary>The ground the camp stands on: its weather is the band's weather.</summary>"""),
])
patch('People/Person.cs',[("        public double WinterLow = 1;","""        /// <summary>The leanest this person has been so far this season (fed and fat, 0-1).</summary>
        public double WinterLow = 1;""")])
patch('Activities/Decider.cs',[
("""        /// <summary>
        /// How strongly someone feels the need to put food by for winter: how lean they remember
        /// winters being, how patient they are, and how far short of enough the camp's keeping-food is.
        /// Only felt as winter approaches.
        /// </summary>
        public static double Foresight(Simulation sim, Person p)
        {
            var season = sim.Clock.Season;
            if (season != Season.Autumn && !(season == Season.Summer && sim.Clock.DayOfSeason > 45)) return 0;
            double lean = p.Expect.Get("lean:season", 0.2);
            var home = sim.HomeOf(p);
            // Enough keeping-food in their own hearth to carry them through as much of the lean months
            // (winter and spring, until the land greens) as they expect to go hungry.
            double enough = home.Members.Count * 0.9 * SimClock.DaysPerSeason * 2 * lean;
            // Keeping-food is anything that lasts: nuts and grain, and whatever has been dried.
            double shortfall = enough <= 0 ? 0 : Inheritance.Clamp01(1 - (home.Food.Stored + home.Food.Dried) / enough);
            return lean * (0.5 + p.M(MindTrait.Patience) * 0.5) * shortfall;
        }""",
"""        /// <summary>
        /// How strongly someone feels the need to put food by: how lean they've learned the coming two
        /// seasons get (the nearer one counting more), how patient they are, and how far short of
        /// enough their hearth's keeping-food is. No calendar: it rises as seasons they know to be lean
        /// draw near, so a band that has never gone hungry doesn't bother, and one that has learned
        /// its springs are hard starts storing in the autumn.
        /// </summary>
        public static double Foresight(Simulation sim, Person p)
        {
            int s = (int)sim.Clock.Season;
            double next = p.Expect.Get(Simulation.LeanTopic((Season)((s + 1) % 4)), 0.2);
            double after = p.Expect.Get(Simulation.LeanTopic((Season)((s + 2) % 4)), 0.2);
            double ahead = next * 0.6 + after * 0.4;
            return ahead * (0.5 + p.M(MindTrait.Patience) * 0.5) * StoreShortfall(sim, p, next, after);
        }

        /// <summary>
        /// How far short (0-1) the hearth's keeping-food (nuts, grain, dried food) is of carrying it through
        /// as much of the coming two seasons as they expect to go hungry.
        /// </summary>
        static double StoreShortfall(Simulation sim, Person p, double next, double after)
        {
            var home = sim.HomeOf(p);
            double enough = home.Members.Count * 0.9 * SimClock.DaysPerSeason * (next + after);
            return enough <= 0 ? 0 : Inheritance.Clamp01(1 - (home.Food.Stored + home.Food.Dried) / enough);
        }

        /// <summary>The rations of keeping-food someone's hearth is short for the lean seasons they expect.</summary>
        public static double StoreShortfallRations(Simulation sim, Person p)
        {
            int s = (int)sim.Clock.Season;
            double next = p.Expect.Get(Simulation.LeanTopic((Season)((s + 1) % 4)), 0.2), after = p.Expect.Get(Simulation.LeanTopic((Season)((s + 2) % 4)), 0.2);
            var home = sim.HomeOf(p);
            return Math.Max(0, home.Members.Count * 0.9 * SimClock.DaysPerSeason * (next + after) - home.Food.Stored - home.Food.Dried);
        }"""),
# Uniform: the urge to store adds to any work whose food can be kept.
("""                double drive = 0.25 * room + hunger * 1.5 + Foresight(sim, p) * 1.2;""","""                // Nuts and grain keep: the urge to store pulls toward gathering them.
                double drive = 0.25 * room + hunger * 1.5 + Foresight(sim, p);"""),
("""Foresight(sim, p) * (Preserve.CanPreserve(p) ? 1.0 : 0.6);""","""(Preserve.CanPreserve(p) ? Foresight(sim, p) : 0);   // fish keeps only for those who can dry it"""),
("""                // Those who know how to dry meat hunt hard in the autumn, while the game is fat, for the winter.
                double drive = 0.25 * huntRoom + Math.Max(hunger, meatHunger * 0.7 * meatRoom) * 1.5
                               + (Preserve.CanPreserve(p) ? Foresight(sim, p) * 0.8 : 0);""",
"""                // Meat keeps only for those who can dry it: for them, the urge to store counts here too.
